) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `blog_faqs`;
CREATE TABLE `blog_faqs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `blog_id` bigint(20) unsigned NOT NULL,
  `question` text NOT NULL,
  `answer` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `blog_faqs_blog_id_foreign` (`blog_id`),
  CONSTRAINT `blog_faqs_blog_id_foreign` FOREIGN KEY (`blog_id`) REFERENCES `blogs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `blog_faqs` (`id`, `blog_id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('1', '1', 'What is online education?', '<p data-start=\"245\" data-end=\"473\">Online education is a learning method where students study through the internet using digital platforms. It includes video lectures, live classes, assignments, and quizzes that can be accessed anytime and anywhere.</p>', '2026-04-11 12:07:29', '2026-04-11 12:07:29');
INSERT INTO `blog_faqs` (`id`, `blog_id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('2', '1', 'Is online learning effective compared to traditional education?', '<p data-start=\"553\" data-end=\"799\">Yes, online learning can be highly effective when done with discipline. It offers flexibility, access to global resources, and the ability to learn at your own pace, making it a strong alternative to traditional classroom education.</p>', '2026-04-11 12:08:02', '2026-04-11 12:08:02');
INSERT INTO `blog_faqs` (`id`, `blog_id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('3', '1', 'What are the benefits of online education?', '<p data-start=\"858\" data-end=\"1052\">Online education provides flexibility, cost savings, access to global instructors, self-paced learning, and the ability to study from any location without geographical limitations.</p>', '2026-04-11 12:08:36', '2026-04-11 12:08:36');
INSERT INTO `blog_faqs` (`id`, `blog_id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('4', '2', 'What equipment do I need for online learning?', '<p data-start=\"1114\" data-end=\"1256\">You typically need a smartphone or computer, a stable internet connection, headphones, and access to a learning platform or app.</p>', '2026-04-11 12:09:33', '2026-04-11 12:09:33');

DROP TABLE IF EXISTS `blogs`;
CREATE TABLE `blogs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `alt` varchar(255) NOT NULL,
  `content` longtext NOT NULL,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `short_content` text NOT NULL,
  `view` bigint(20) unsigned NOT NULL DEFAULT 0,
  `meta_titel` varchar(255) NOT NULL,
  `meta_description` text DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `ld_schema` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `blogs` (`id`, `name`, `image`, `alt`, `content`, `category_id`, `short_content`, `view`, `meta_titel`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('1', 'Online & Distance Education in India: Courses, Benefits & Career Scope', 'new-assets/img/blog/banner/online-distance-education-in-india-courses-benefits-career-scope_banner.jpg', 'blogmba', '<h2 style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(17, 24, 39);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:32px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;line-height:1.2;margin-bottom:0px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"745\" data-end=\"801\"><strong>Why Online &amp; Distance Education Is Gaining Popularity</strong></h2><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"802\" data-end=\"866\">Here’s why lakhs of students are choosing this mode of learning:</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"868\" data-end=\"1283\"><strong style=\"box-sizing:border-box;outline:none;\" data-start=\"870\" data-end=\"886\">Flexibility:</strong> Learn at your own pace while managing work or personal commitments</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"868\" data-end=\"1283\"><strong style=\"box-sizing:border-box;outline:none;\" data-start=\"958\" data-end=\"978\">Affordable Fees:</strong> Lower tuition and no relocation costs</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"868\" data-end=\"1283\"><strong style=\"box-sizing:border-box;outline:none;\" data-start=\"1021\" data-end=\"1044\">Recognized Degrees:</strong> UGC-approved online degrees are valid for jobs and higher studies</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"868\" data-end=\"1283\"><strong style=\"box-sizing:border-box;outline:none;\" data-start=\"1115\" data-end=\"1139\">Wide Course Options:</strong> From BA, B.Com, BBA to MBA, MCA, M.Sc and more</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"868\" data-end=\"1283\"><strong style=\"box-sizing:border-box;outline:none;\" data-start=\"1191\" data-end=\"1213\">Career Continuity:</strong> Ideal for working professionals seeking promotion or skill upgrades</p><h2 style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(17, 24, 39);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:32px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;line-height:1.2;margin-bottom:0px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1285\" data-end=\"1334\"><strong>Who Should Choose Online or Distance Learning?</strong></h2><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1335\" data-end=\"1380\">Online and distance education is perfect for:</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1381\" data-end=\"1594\">Working professionals</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1381\" data-end=\"1594\">Students unable to attend regular college</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1381\" data-end=\"1594\">Homemakers restarting their careers</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1381\" data-end=\"1594\">Entrepreneurs upgrading qualifications</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1381\" data-end=\"1594\">Learners preparing for government or competitive exams</p><h2 style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(17, 24, 39);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:32px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;line-height:1.2;margin-bottom:0px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1596\" data-end=\"1641\"><strong>Popular Online &amp; Distance Courses in India</strong></h2><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1642\" data-end=\"1686\">Some of the most in-demand programs include:</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1687\" data-end=\"1849\">Online &amp; Distance <strong style=\"box-sizing:border-box;outline:none;\" data-start=\"1707\" data-end=\"1714\">MBA</strong> (HR, Finance, Marketing, IT, Operations)</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1687\" data-end=\"1849\">Online <strong style=\"box-sizing:border-box;outline:none;\" data-start=\"1767\" data-end=\"1787\">BBA / B.Com / BA</strong></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1687\" data-end=\"1849\">Distance <strong style=\"box-sizing:border-box;outline:none;\" data-start=\"1801\" data-end=\"1822\">M.Com / MA / M.Sc</strong></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1687\" data-end=\"1849\">Online <strong style=\"box-sizing:border-box;outline:none;\" data-start=\"1834\" data-end=\"1847\">BCA / MCA</strong></p><h2 style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(17, 24, 39);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:32px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;line-height:1.2;margin-bottom:0px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1851\" data-end=\"1898\"><strong>Career Scope After Online &amp; Distance Degrees</strong></h2><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1899\" data-end=\"1938\">Graduates can explore opportunities in:</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1939\" data-end=\"2103\">Corporate and private sectors</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1939\" data-end=\"2103\">Government jobs (subject to eligibility norms)</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(78, 85, 97);font-family:&quot;IBM Plex Sans&quot;, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:20px;margin-top:0px;orphans:2;outline:none;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"1939\" data-end=\"2103\">Higher education (PhD, certifications)</p>', NULL, 'Online & Distance Education in India: Courses, Benefits & Career ScopeOnline & Distance Education in India: Courses, Benefits & Career ScopeOnline & Distance Education in India: Courses, Benefits & Career ScopeOnline & Distance Education in India: Courses, Benefits & Career Scope', '9', 'online-mba', 'online-mba', 'online-mba', NULL, '1', '2026-04-11 06:47:13', '2026-04-11 12:09:53');
INSERT INTO `blogs` (`id`, `name`, `image`, `alt`, `content`, `category_id`, `short_content`, `view`, `meta_titel`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('2', 'Benefits of Distance Learning for Working Professionals', 'new-assets/img/blog/banner/benefits-of-distance-learning-for-working-professionals_banner.png', 'Distance Learning Benefits', '<p>Distance learning has become a popular choice among working professionals who want to continue their education without compromising their careers. It offers flexibility, allowing learners to study at their own pace and schedule. With online resources, recorded lectures, and digital assignments, students can manage both work and studies effectively. This mode of education is cost-effective and accessible from anywhere, making it ideal for career growth.</p>', NULL, 'Distance learning allows professionals to upgrade skills without leaving their jobs.', '1', 'benefits-of-distance-learning', 'Distance learning allows professionals to upgrade skills without leaving their jobs.', 'benefits-of-distance-learning', NULL, '1', '2026-04-11 08:25:16', '2026-04-11 11:16:07');
INSERT INTO `blogs` (`id`, `name`, `image`, `alt`, `content`, `category_id`, `short_content`, `view`, `meta_titel`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('3', 'Top Career Options After Graduation', 'new-assets/img/blog/banner/top-career-options-after-graduation_banner.webp', 'Career Options', '<p>After completing graduation, students have multiple career paths to choose from, including higher education, professional courses, or entering the workforce. Popular options include MBA, MCA, digital marketing, data analysis, and government jobs. Choosing the right path depends on your interests, skills, and long-term goals. Proper guidance and research can help you make the best decision for a successful career.</p>', NULL, 'Explore the best career paths you can choose after completing your graduation.', '44', 'career-options-after-graduation', 'Explore the best career paths you can choose after completing your graduation.', 'career-options-after-graduation', NULL, '1', '2026-04-11 08:27:01', '2026-04-15 09:40:39');
INSERT INTO `blogs` (`id`, `name`, `image`, `alt`, `content`, `category_id`, `short_content`, `view`, `meta_titel`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('4', 'Importance of Skill-Based Education', 'new-assets/img/blog/banner/importance-of-skill-based-education_banner.webp', 'skill-based', '<p>Skill-based education focuses on practical knowledge rather than just theoretical learning. It prepares students for real-world challenges and improves employability. Courses like digital marketing, programming, and business analytics are in high demand. Learning skills alongside academic education ensures better career opportunities and growth.</p>', NULL, 'Skill-based education helps students become job-ready and industry-focused.', '6', 'importance-of-skill-based-education', 'Skill-based education helps students become job-ready and industry-focused.', 'importance-of-skill-based-education', NULL, '1', '2026-04-11 08:29:14', '2026-04-17 11:21:37');

DROP TABLE IF EXISTS `course_faqs`;
CREATE TABLE `course_faqs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `course_id` bigint(20) unsigned NOT NULL,
  `question` text NOT NULL,
  `answer` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `course_faqs_course_id_foreign` (`course_id`),
  CONSTRAINT `course_faqs_course_id_foreign` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned NOT NULL,
  `department_id` bigint(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `image` varchar(255) NOT NULL,
  `alt` varchar(255) NOT NULL,
  `duration` varchar(255) NOT NULL,
  `eligibilty` varchar(255) NOT NULL,
  `fees` varchar(255) NOT NULL,
  `content` longtext NOT NULL,
  `short_content` text NOT NULL,
  `meta_title` varchar(255) NOT NULL,
  `meta_description` text NOT NULL,
  `slug` varchar(255) NOT NULL,
  `ld_schema` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(11) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

