e=\"--bs-table-accent-bg:rgba(var(--dark-rgb),0.0125);--bs-table-bg-type:rgba(0,0,0, 0.05);--bs-table-color-type:#000;background-color:rgb(255, 255, 255);border-bottom-width:0px;border-color:inherit;border-left-width:1px;border-right-width:1px;border-style:solid;border-top-width:0px;box-shadow:rgba(0, 0, 0, 0.05) 0px 0px 0px 9999px inset;box-sizing:border-box;color:rgb(78, 85, 97);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\"><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:0px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\" times=\"\" new=\"\">Assignments + Term-end Exams</span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p></td></tr><tr style=\"border-bottom-width:1px;border-color:rgb(231, 237, 242);border-left-width:0px;border-right-width:0px;border-style:solid;border-top-width:1px;box-sizing:border-box;outline:none;\"><td style=\"background-color:rgb(255, 255, 255);border-bottom-width:0px;border-color:inherit;border-left-width:1px;border-right-width:1px;border-style:solid;border-top-width:0px;box-shadow:rgba(0, 0, 0, 0) 0px 0px 0px 9999px inset;box-sizing:border-box;color:rgb(101, 107, 118);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\"><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:0px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\" times=\"\" new=\"\"><strong style=\"box-sizing:border-box;outline:none;\">Specialisations</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p></td><td style=\"background-color:rgb(255, 255, 255);border-bottom-width:0px;border-color:inherit;border-left-width:1px;border-right-width:1px;border-style:solid;border-top-width:0px;box-shadow:rgba(0, 0, 0, 0) 0px 0px 0px 9999px inset;box-sizing:border-box;color:rgb(101, 107, 118);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\"><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:0px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Accounting &amp; Finance, Banking &amp; Finance, Taxation, Auditing, International Business, Financial Markets</span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p></td></tr></tbody></table></figure></div></figure><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Subjects &amp; Syllabus</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">The Online B.Com curriculum focuses on commerce, economics, taxation, finance, and business management to enhance analytical and managerial skills.</span>&nbsp;<br><br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Core Subjects:</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Financial Accounting</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Business Law</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Micro &amp; Macro Economics</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Cost Accounting</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Income Tax Law &amp; Practice</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Corporate Accounting</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Business Statistics</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Management Principles</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Auditing &amp; Assurance</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Marketing Management</span>&nbsp;<br><br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Elective / Specialization Subjects:</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Banking &amp; Insurance</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- E-Commerce</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Financial Management</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Human Resource Management</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Entrepreneurship Development</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Business Communication</span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Eligibility &amp; Duration</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Eligibility: Students must have completed 10+2 (any stream) from a recognized board.</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Minimum Duration: 3 years (6 semesters)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Maximum Duration: 6 years (flexible as per university rules)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- No Age Limit: Open to all learners</span></p><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Admission Procedure</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">1. Register Online and fill out the application form.</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">2. Upload Required Documents: 10th &amp; 12th Mark Sheets, ID Proof, Photo, Signature.</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">3. Pay the Application/Admission Fee.</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">4. Get Confirmation and access your student login or LMS credentials.</span>&nbsp;<br><br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Admissions are typically open twice a year – January and July sessions.</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Top Specializations</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in Accounting &amp; Finance</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in Banking &amp; Insurance</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in International Business</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in Computer Applications</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in Taxation</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in Economics</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in Marketing Management</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- B.Com in Corporate Secretaryship</span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Is an Online B.Com Worth It?</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Yes, pursuing an Online B.Com is absolutely worth it! It is UGC-DEB-approved and holds the same value as a regular degree. The flexibility to study while working or managing other commitments makes it a perfect choice for working professionals, entrepreneurs, students preparing for CA, CS, CMA, or MBA, and individuals seeking cost-effective higher education.</span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Recognitions &amp; Approvals</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Before enrolling, ensure your chosen university is approved by:</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- UGC (University Grants Commission)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- DEB (Distance Education Bureau)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- AICTE (for technical components)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- NAAC Accreditation (for quality assurance)</span>&nbsp;<br><br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Degrees from UGC-DEB-recognized universities are valid for all government and private jobs, as well as for pursuing higher studies in India and abroad.</span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Career Scope After B.Com</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">A B.Com graduate is qualified for a variety of roles in finance, accounting, and management.</span>&nbsp;<br><br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Top Career Options:</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Accountant / Financial Analyst</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Auditor / Tax Consultant</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Banker / Investment Advisor</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Business Executive / Manager</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- E-commerce Specialist</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Chartered Accountant (with further qualification)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Company Secretary / Cost Accountant</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- Civil Services (UPSC, SSC, etc.)</span>&nbsp;<br><br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">Higher Studies Options:</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- M.Com (Master of Commerce)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- MBA (Master of Business Administration)</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- CA / CS / CMA</span>&nbsp;<br><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">- LLB (Law)</span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></p><h4 style=\"box-sizing:border-box;color:rgb(17, 24, 39);font-family:;\" ibm=\"\" plex=\"\" sans\",=\"\" sans-serif;font-size:32px;line-height:1.2;margin-bottom:0px;margin-top:0px;outline:none;\"=\"\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\"><strong>Conclusion</strong></span><o:p style=\"box-sizing:border-box;outline:none;\"></o:p></h4><p class=\"MsoNormal\" style=\"box-sizing:border-box;margin-bottom:20px;margin-top:0px;outline:none;\"><span style=\"box-sizing:border-box;outline:none;\" lang=\"EN-US\" dir=\"ltr\">The Online B.Com program in India is a smart choice for students and professionals seeking a career in business, commerce, or finance. With flexible learning, recognized accreditation, and diverse career opportunities, it offers unmatched value for money. Choose a UGC-DEB-approved university, study at your own pace, and open the doors to a successful corporate or entrepreneurial career.</span></p></div>', 'B.Com (Bachelor of Commerce) is a 3-year undergraduate commerce program designed for students who want to build strong knowledge in accounting, finance, taxation, business law, and economics with complete learning flexibility. This program is ideal for 12th-pass students and working individuals preparing for CA, CMA, CS, banking, and finance careers. It includes online classes, digital study material, and virtual exams, offered by UGC-DEB-approved universities.', 'bcom', 'B.Com (Bachelor of Commerce) is a 3-year undergraduate commerce program designed for students who want to build strong knowledge in accounting, finance, taxation, business law, and economics with complete learning flexibility. This program is ideal for 12th-pass students and working individuals preparing for CA, CMA, CS, banking, and finance careers. It includes online classes, digital study material, and virtual exams, offered by UGC-DEB-approved universities.', 'bcom', NULL, '1', '2026-04-11 06:05:22', '2026-04-17 11:00:55');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('2', '3', '1', 'B.B.A', 'Bachelor of Business Administration', 'new-assets/img/courses/bba_banner.png', 'BBA', '3 year', '10+2 pass with minimum 45% marks from a recognized board in any stream (Commerce, Science, or Arts), with English as a compulsory subject.', '₹10,000 per semester', '<h6 data-section-id=\"1otz26t\" data-start=\"102\" data-end=\"121\"><span role=\"text\"><strong data-start=\"105\" data-end=\"121\">About Course</strong></span></h6><p data-start=\"122\" data-end=\"626\">The <strong data-start=\"126\" data-end=\"173\">Bachelor of Business Administration (B.B.A)</strong> program is a dynamic undergraduate degree designed for students who want to build a strong foundation in business management, leadership, entrepreneurship, and corporate skills. It is ideal for students aiming to pursue careers in management, marketing, finance, human resources, and business operations. The program focuses on practical learning, case studies, internships, and industry exposure to prepare students for real-world business challenges.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"633\" data-end=\"652\"><span role=\"text\"><strong data-start=\"636\" data-end=\"652\">Key Features</strong></span></h6><div class=\"TyagGW_tableContainer\"><div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\"><figure class=\"table\"><table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"654\" data-end=\"1335\"><thead data-start=\"654\" data-end=\"671\"><tr data-start=\"654\" data-end=\"671\"><th class=\"\" data-start=\"654\" data-end=\"668\" data-col-size=\"sm\"><strong data-start=\"656\" data-end=\"667\">Details</strong></th><th class=\"\" data-start=\"668\" data-end=\"671\" data-col-size=\"md\">&nbsp;</th></tr></thead><tbody data-start=\"690\" data-end=\"1335\"><tr data-start=\"690\" data-end=\"751\"><td data-start=\"690\" data-end=\"712\" data-col-size=\"sm\"><strong data-start=\"692\" data-end=\"711\">Programme Title</strong></td><td data-col-size=\"md\" data-start=\"712\" data-end=\"751\">Bachelor of Business Administration</td></tr><tr data-start=\"752\" data-end=\"781\"><td data-start=\"752\" data-end=\"764\" data-col-size=\"sm\"><strong data-start=\"754\" data-end=\"763\">Level</strong></td><td data-col-size=\"md\" data-start=\"764\" data-end=\"781\">Undergraduate</td></tr><tr data-start=\"782\" data-end=\"822\"><td data-start=\"782\" data-end=\"797\" data-col-size=\"sm\"><strong data-start=\"784\" data-end=\"796\">Duration</strong></td><td data-col-size=\"md\" data-start=\"797\" data-end=\"822\">3 Years (6 Semesters)</td></tr><tr data-start=\"823\" data-end=\"874\"><td data-start=\"823\" data-end=\"843\" data-col-size=\"sm\"><strong data-start=\"825\" data-end=\"842\">Mode of Study</strong></td><td data-col-size=\"md\" data-start=\"843\" data-end=\"874\">Regular / Online / Distance</td></tr><tr data-start=\"875\" data-end=\"933\"><td data-start=\"875\" data-end=\"893\" data-col-size=\"sm\"><strong data-start=\"877\" data-end=\"892\">Affiliation</strong></td><td data-col-size=\"md\" data-start=\"893\" data-end=\"933\">UGC, AICTE, NAAC (as per university)</td></tr><tr data-start=\"934\" data-end=\"1005\"><td data-start=\"934\" data-end=\"961\" data-col-size=\"sm\"><strong data-start=\"936\" data-end=\"960\">Eligibility Criteria</strong></td><td data-col-size=\"md\" data-start=\"961\" data-end=\"1005\">10+2 (any stream) with minimum 45% marks</td></tr><tr data-start=\"1006\" data-end=\"1120\"><td data-start=\"1006\" data-end=\"1026\" data-col-size=\"sm\"><strong data-start=\"1008\" data-end=\"1025\">Core Subjects</strong></td><td data-col-size=\"md\" data-start=\"1026\" data-end=\"1120\">Principles of Management, Marketing, Finance, HR, Business Communication, Entrepreneurship</td></tr><tr data-start=\"1121\" data-end=\"1172\"><td data-start=\"1121\" data-end=\"1140\" data-col-size=\"sm\"><strong data-start=\"1123\" data-end=\"1139\">Average Fees</strong></td><td data-col-size=\"md\" data-start=\"1140\" data-end=\"1172\">₹10,000 per semester</td></tr><tr data-start=\"1173\" data-end=\"1243\"><td data-start=\"1173\" data-end=\"1203\" data-col-size=\"sm\"><strong data-start=\"1175\" data-end=\"1202\">Assessment &amp; Evaluation</strong></td><td data-col-size=\"md\" data-start=\"1203\" data-end=\"1243\">Internal Assessment + Semester Exams</td></tr><tr data-start=\"1244\" data-end=\"1335\"><td data-start=\"1244\" data-end=\"1266\" data-col-size=\"sm\"><strong data-start=\"1246\" data-end=\"1265\">Specialisations</strong></td><td data-col-size=\"md\" data-start=\"1266\" data-end=\"1335\">Marketing, Finance, HR, International Business, Digital Marketing</td></tr></tbody></table></figure></div></div><hr><h6 data-section-id=\"rh3c0z\" data-start=\"1342\" data-end=\"1368\"><span role=\"text\"><strong data-start=\"1345\" data-end=\"1368\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"1369\" data-end=\"1471\">The BBA curriculum focuses on business management, leadership skills, and industry-oriented knowledge.</p><h6 data-section-id=\"1ogneya\" data-start=\"1473\" data-end=\"1494\"><span role=\"text\"><strong>Core Subjects</strong></span></h6><p data-start=\"1495\" data-end=\"1757\">Principles of Management</p><p data-start=\"1495\" data-end=\"1757\">Business Communication</p><p data-start=\"1495\" data-end=\"1757\">Financial Management</p><p data-start=\"1495\" data-end=\"1757\">Marketing Management</p><p data-start=\"1495\" data-end=\"1757\">Human Resource Management</p><p data-start=\"1495\" data-end=\"1757\">Business Economics</p><p data-start=\"1495\" data-end=\"1757\">Organizational Behavior</p><p data-start=\"1495\" data-end=\"1757\">Business Law</p><p data-start=\"1495\" data-end=\"1757\">Entrepreneurship Development</p><p data-start=\"1495\" data-end=\"1757\">Operations Management</p><h6 data-section-id=\"1tnkfuw\" data-start=\"1759\" data-end=\"1801\"><span role=\"text\"><strong data-start=\"1763\" data-end=\"1801\">Elective / Specialization Subjects</strong></span></h6><p data-start=\"1802\" data-end=\"1947\">Digital Marketing</p><p data-start=\"1802\" data-end=\"1947\">International Business</p><p data-start=\"1802\" data-end=\"1947\">Retail Management</p><p data-start=\"1802\" data-end=\"1947\">Financial Planning</p><p data-start=\"1802\" data-end=\"1947\">Supply Chain Management</p><p data-start=\"1802\" data-end=\"1947\">Banking &amp; Insurance</p><hr><h6 data-section-id=\"mm6aog\" data-start=\"1954\" data-end=\"1983\"><span role=\"text\"><strong data-start=\"1957\" data-end=\"1983\">Eligibility &amp; Duration</strong></span></h6><p data-start=\"1984\" data-end=\"2216\"><strong data-start=\"1986\" data-end=\"2002\">Eligibility:</strong> 10+2 pass (any stream) from a recognized board with minimum 45% marks</p><p data-start=\"1984\" data-end=\"2216\"><strong data-start=\"2077\" data-end=\"2098\">Minimum Duration:</strong> 3 years (6 semesters)</p><p data-start=\"1984\" data-end=\"2216\"><strong data-start=\"2125\" data-end=\"2146\">Maximum Duration:</strong> 5–6 years (depending on university)</p><p data-start=\"1984\" data-end=\"2216\"><strong data-start=\"2187\" data-end=\"2201\">Age Limit:</strong> No age limit</p><hr><h6 data-section-id=\"12q771d\" data-start=\"2223\" data-end=\"2249\"><span role=\"text\"><strong data-start=\"2226\" data-end=\"2249\">Admission Procedure</strong></span></h6><ol><li data-start=\"2250\" data-end=\"2510\">Fill out the online/offline application form</li><li data-start=\"2250\" data-end=\"2510\">Submit required documents (10th &amp; 12th marksheets, ID proof, photo)</li><li data-start=\"2250\" data-end=\"2510\">Pay admission/application fee</li><li data-start=\"2250\" data-end=\"2510\">Some colleges may conduct entrance exams or interviews</li><li data-start=\"2250\" data-end=\"2510\">Admission confirmation and enrollment</li></ol><p data-start=\"2512\" data-end=\"2593\">Admissions are generally open in <strong data-start=\"2545\" data-end=\"2558\">June–July</strong> and sometimes <strong data-start=\"2573\" data-end=\"2592\">January session</strong>.</p><hr><h6 data-section-id=\"1ex0xgy\" data-start=\"2600\" data-end=\"2626\"><span role=\"text\"><strong data-start=\"2603\" data-end=\"2626\">Top Specializations</strong></span></h6><p data-start=\"2627\" data-end=\"2823\">BBA in Marketing</p><p data-start=\"2627\" data-end=\"2823\">BBA in Finance</p><p data-start=\"2627\" data-end=\"2823\">BBA in Human Resource Management</p><p data-start=\"2627\" data-end=\"2823\">BBA in International Business</p><p data-start=\"2627\" data-end=\"2823\">BBA in Digital Marketing</p><p data-start=\"2627\" data-end=\"2823\">BBA in Entrepreneurship</p><p data-start=\"2627\" data-end=\"2823\">BBA in Banking &amp; Finance</p><hr><h6 data-section-id=\"vo1sdm\" data-start=\"2830\" data-end=\"2853\"><span role=\"text\"><strong data-start=\"2833\" data-end=\"2853\">Is BBA Worth It?</strong></span></h6><p data-start=\"2854\" data-end=\"3148\">Yes, pursuing a BBA is highly valuable for students who want to enter the business and management field. It builds strong fundamentals for corporate careers and higher education like MBA. The course enhances leadership, communication, and decision-making skills, making students industry-ready.</p><hr><h6 data-section-id=\"qz8v37\" data-start=\"3155\" data-end=\"3186\"><span role=\"text\"><strong data-start=\"3158\" data-end=\"3186\">Recognitions &amp; Approvals</strong></span></h6><p data-start=\"3187\" data-end=\"3251\">Before taking admission, ensure the university is approved by:</p><ul><li data-start=\"3252\" data-end=\"3339\">UGC (University Grants Commission)</li><li data-start=\"3252\" data-end=\"3339\">AICTE (if applicable)</li><li data-start=\"3252\" data-end=\"3339\">NAAC Accreditation</li></ul><p data-start=\"3341\" data-end=\"3436\">Degrees from recognized universities are valid for jobs and higher studies in India and abroad.</p><hr><h6 data-section-id=\"1f2uy0\" data-start=\"3443\" data-end=\"3472\"><span role=\"text\"><strong data-start=\"3446\" data-end=\"3472\">Career Scope After BBA</strong></span></h6><h6 data-section-id=\"p64cbj\" data-start=\"3474\" data-end=\"3500\"><span role=\"text\"><strong data-start=\"3478\" data-end=\"3500\">Top Career Options</strong></span></h6><p data-start=\"3501\" data-end=\"3672\">Business Executive / Manager</p><p data-start=\"3501\" data-end=\"3672\">Marketing Executive</p><p data-start=\"3501\" data-end=\"3672\">HR Executive</p><p data-start=\"3501\" data-end=\"3672\">Financial Analyst</p><p data-start=\"3501\" data-end=\"3672\">Sales Manager</p><p data-start=\"3501\" data-end=\"3672\">Entrepreneur / Startup Founder</p><p data-start=\"3501\" data-end=\"3672\">Operations Manager</p><h6 data-section-id=\"1qmqpba\" data-start=\"3674\" data-end=\"3704\"><span role=\"text\"><strong data-start=\"3678\" data-end=\"3704\">Higher Studies Options</strong></span></h6><p data-start=\"3705\" data-end=\"3806\">MBA (Master of Business Administration)</p><p data-start=\"3705\" data-end=\"3806\">PGDM</p><p data-start=\"3705\" data-end=\"3806\">M.Com</p><p data-start=\"3705\" data-end=\"3806\">Professional Courses (CA, CS, CMA)</p><hr><h6 data-section-id=\"9dt57q\" data-start=\"3813\" data-end=\"3830\"><span role=\"text\"><strong data-start=\"3816\" data-end=\"3830\">Conclusion</strong></span></h6><p data-start=\"3831\" data-end=\"4180\">The BBA program is an excellent choice for students aspiring to build a career in business and management. With practical learning, multiple specializations, and wide career opportunities, it provides a strong platform for both corporate jobs and entrepreneurship. Choosing a recognized university ensures quality education and better career growth.</p>', 'The Bachelor of Business Administration (B.B.A) is an undergraduate program that provides a strong foundation in business management, leadership, marketing, finance, and entrepreneurship. The course focuses on practical learning, case studies, and industry exposure to prepare students for real-world business challenges.', 'general-bba', 'The Bachelor of Business Administration (B.B.A) is an undergraduate program that provides a strong foundation in business management, leadership, marketing, finance, and entrepreneurship. The course focuses on practical learning, case studies, and industry exposure to prepare students for real-world business challenges.', 'general-bba', NULL, '1', '2026-04-13 07:42:55', '2026-04-17 11:03:14');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('3', '3', '1', 'B.Sc.', 'Bachelor of Science', 'new-assets/img/courses/bsc_banner.png', 'bsc-image', '3 year', '10+2 (any stream) from a recognized board', '₹10,000 per semester', '<div><div class=\"flex h-svh w-screen flex-col\"><div class=\"relative z-0 flex min-h-0 w-full flex-1\"><div class=\"relative flex min-h-0 w-full flex-1\"><div class=\"@container/main relative flex min-w-0 flex-1 flex-col -translate-y-[calc(env(safe-area-inset-bottom,0px)/2)] pt-[calc(env(safe-area-inset-bottom,0px)/2)]\"><div class=\"@w-sm/main:[scrollbar-gutter:var(--stage-scroll-gutter)] touch:[scrollbar-width:none] group/scroll-root relative flex min-h-0 min-w-0 flex-1 flex-col [scrollbar-gutter:stable] not-print:overflow-x-clip not-print:overflow-y-auto group-data-stream-active/scroll-root:[overflow-anchor:none] scroll-pt-(--header-height) [--sticky-padding-top:var(--header-height)] [--sticky-padding-bottom:0px] [--scroll-root-safe-area-inset-top:calc(var(--sticky-padding-top)+env(safe-area-inset-top,0px))] [--scroll-root-safe-area-inset-bottom:calc(var(--sticky-padding-bottom)+var(--screen-keyboard-height,0px)+env(safe-area-inset-bottom,0px))] [--scroll-root-safe-area-height:calc(100lvh-var(--scroll-root-safe-area-inset-top)-var(--scroll-root-safe-area-inset-bottom))] has-data-[fixed-header=less-than-xl]:@w-xl/main:scroll-pt-0 has-data-[fixed-header=less-than-xl]:@w-xl/main:[--sticky-padding-top:0px] has-data-[fixed-header=less-than-xxl]:@w-2xl/main:scroll-pt-0 has-data-[fixed-header=less-than-xxl]:@w-2xl/main:[--sticky-padding-top:0px]\" data-scroll-root=\"\" data-scroll-from-top=\"\"><main class=\"min-h-0 flex-1\" id=\"main\" z-index=\"-1\"><div class=\"group/thread flex flex-col min-h-full\" id=\"thread\"><div class=\"composer-parent flex flex-1 flex-col focus-visible:outline-0\" role=\"presentation\"><div class=\"relative basis-auto flex-col -mb-(--composer-overlap-px) pb-(--composer-overlap-px) [--composer-overlap-px:28px] grow flex\"><div class=\"flex flex-col text-sm pb-25\"><section class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:c77d5c3e-9a91-45b7-b8f4-bfc480df34db-18\" data-testid=\"conversation-turn-38\" data-scroll-anchor=\"true\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-message-author-role=\"assistant\" data-message-id=\"ded0dd28-eb22-4546-b31f-dc3e3acfb94d\" dir=\"auto\" data-message-model-slug=\"gpt-5-3\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\"><h6 data-section-id=\"19wm21h\" data-start=\"96\" data-end=\"117\"><span role=\"text\"><strong data-start=\"99\" data-end=\"115\">About Course</strong></span></h6><p data-start=\"118\" data-end=\"557\">The Bachelor of Science (B.Sc) program is an undergraduate degree designed for students who want to build a strong foundation in scientific knowledge, analytical thinking, and research skills. It is ideal for students aiming to pursue careers in science, research, healthcare, IT, and education. The program focuses on theoretical concepts along with practical and laboratory-based learning to prepare students for real-world applications.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"564\" data-end=\"583\"><span role=\"text\"><strong data-start=\"567\" data-end=\"583\">Key Features</strong></span></h6><div class=\"TyagGW_tableContainer\"><div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\"><figure class=\"table\"><table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"585\" data-end=\"1242\"><thead data-start=\"585\" data-end=\"602\"><tr data-start=\"585\" data-end=\"602\"><th class=\"\" data-start=\"585\" data-end=\"599\" data-col-size=\"sm\"><p style=\"text-align:center;\"><strong data-start=\"587\" data-end=\"598\">Details</strong></p></th><th class=\"\" data-start=\"599\" data-end=\"602\" data-col-size=\"md\">&nbsp;</th></tr></thead><tbody data-start=\"621\" data-end=\"1242\"><tr data-start=\"621\" data-end=\"666\"><td data-start=\"621\" data-end=\"643\" data-col-size=\"sm\"><strong data-start=\"623\" data-end=\"642\">Programme Title</strong></td><td data-col-size=\"md\" data-start=\"643\" data-end=\"666\"><p style=\"text-align:center;\">Bachelor of Science</p></td></tr><tr data-start=\"667\" data-end=\"696\"><td data-start=\"667\" data-end=\"679\" data-col-size=\"sm\"><strong data-start=\"669\" data-end=\"678\">Level</strong></td><td data-col-size=\"md\" data-start=\"679\" data-end=\"696\"><p style=\"text-align:center;\">Undergraduate</p></td></tr><tr data-start=\"697\" data-end=\"737\"><td data-start=\"697\" data-end=\"712\" data-col-size=\"sm\"><strong data-start=\"699\" data-end=\"711\">Duration</strong></td><td data-col-size=\"md\" data-start=\"712\" data-end=\"737\"><p style=\"text-align:center;\">3 Years (6 Semesters)</p></td></tr><tr data-start=\"738\" data-end=\"789\"><td data-start=\"738\" data-end=\"758\" data-col-size=\"sm\"><strong data-start=\"740\" data-end=\"757\">Mode of Study</strong></td><td data-col-size=\"md\" data-start=\"758\" data-end=\"789\"><p style=\"text-align:center;\">Regular / Online / Distance</p></td></tr><tr data-start=\"790\" data-end=\"848\"><td data-start=\"790\" data-end=\"808\" data-col-size=\"sm\"><strong data-start=\"792\" data-end=\"807\">Affiliation</strong></td><td data-col-size=\"md\" data-start=\"808\" data-end=\"848\"><p style=\"text-align:center;\">UGC, AICTE, NAAC (as per university)</p></td></tr><tr data-start=\"849\" data-end=\"924\"><td data-start=\"849\" data-end=\"876\" data-col-size=\"sm\"><strong data-start=\"851\" data-end=\"875\">Eligibility Criteria</strong></td><td data-col-size=\"md\" data-start=\"876\" data-end=\"924\"><p style=\"text-align:center;\">10+2 (Science stream) with minimum 45% marks</p></td></tr><tr data-start=\"925\" data-end=\"1007\"><td data-start=\"925\" data-end=\"945\" data-col-size=\"sm\"><strong data-start=\"927\" data-end=\"944\">Core Subjects</strong></td><td data-col-size=\"md\" data-start=\"945\" data-end=\"1007\"><p style=\"text-align:center;\">Physics, Chemistry, Biology, Mathematics, Computer Science</p></td></tr><tr data-start=\"1008\" data-end=\"1059\"><td data-start=\"1008\" data-end=\"1027\" data-col-size=\"sm\"><strong data-start=\"1010\" data-end=\"1026\">Average Fees</strong></td><td data-col-size=\"md\" data-start=\"1027\" data-end=\"1059\"><p style=\"text-align:center;\">₹10,000 per semester</p></td></tr><tr data-start=\"1060\" data-end=\"1142\"><td data-start=\"1060\" data-end=\"1090\" data-col-size=\"sm\"><strong data-start=\"1062\" data-end=\"1089\">Assessment &amp; Evaluation</strong></td><td data-col-size=\"md\" data-start=\"1090\" data-end=\"1142\"><p style=\"text-align:center;\">Internal Assessment + Practical + Semester Exams</p></td></tr><tr data-start=\"1143\" data-end=\"1242\"><td data-start=\"1143\" data-end=\"1165\" data-col-size=\"sm\"><strong data-start=\"1145\" data-end=\"1164\">Specialisations</strong></td><td data-col-size=\"md\" data-start=\"1165\" data-end=\"1242\"><p style=\"text-align:center;\">Physics, Chemistry, Mathematics, Biology, Computer Science, Biotechnology</p></td></tr></tbody></table></figure></div></div><hr><h6 data-section-id=\"g1fqn7\" data-start=\"1249\" data-end=\"1277\"><span role=\"text\"><strong data-start=\"1252\" data-end=\"1275\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"1278\" data-end=\"1375\">The B.Sc curriculum focuses on scientific knowledge, research skills, and practical applications.</p><h6 data-section-id=\"1ogneya\" data-start=\"1377\" data-end=\"1398\"><span role=\"text\"><strong data-start=\"1381\" data-end=\"1398\">Core Subjects</strong></span></h6><ul><li data-start=\"1399\" data-end=\"1532\">Physics</li><li data-start=\"1399\" data-end=\"1532\">Chemistry</li><li data-start=\"1399\" data-end=\"1532\">Mathematics / Biology</li><li data-start=\"1399\" data-end=\"1532\">Computer Science</li><li data-start=\"1399\" data-end=\"1532\">Environmental Science</li><li data-start=\"1399\" data-end=\"1532\">Statistics</li><li data-start=\"1399\" data-end=\"1532\">Laboratory Work</li></ul><h6 data-section-id=\"1tnkfuw\" data-start=\"1534\" data-end=\"1576\"><span role=\"text\"><strong data-start=\"1538\" data-end=\"1576\">Elective / Specialization Subjects</strong></span></h6><ul><li data-start=\"1577\" data-end=\"1684\">Biotechnology</li><li data-start=\"1577\" data-end=\"1684\">Microbiology</li><li data-start=\"1577\" data-end=\"1684\">Data Science</li><li data-start=\"1577\" data-end=\"1684\">Information Technology</li><li data-start=\"1577\" data-end=\"1684\">Genetics</li><li data-start=\"1577\" data-end=\"1684\">Electronics</li></ul><hr><h6 data-section-id=\"mm6aog\" data-start=\"1691\" data-end=\"1720\"><span role=\"text\"><strong data-start=\"1694\" data-end=\"1720\">Eligibility &amp; Duration</strong></span></h6><ul><li data-start=\"1721\" data-end=\"1957\"><strong data-start=\"1723\" data-end=\"1739\">Eligibility:</strong> 10+2 pass (Science stream) from a recognized board with minimum 45% marks</li><li data-start=\"1721\" data-end=\"1957\"><strong data-start=\"1818\" data-end=\"1839\">Minimum Duration:</strong> 3 years (6 semesters)</li><li data-start=\"1721\" data-end=\"1957\"><strong data-start=\"1866\" data-end=\"1887\">Maximum Duration:</strong> 5–6 years (depending on university)</li><li data-start=\"1721\" data-end=\"1957\"><strong data-start=\"1928\" data-end=\"1942\">Age Limit:</strong> No age limit</li></ul><hr><h6 data-section-id=\"12q771d\" data-start=\"1964\" data-end=\"1990\"><span role=\"text\"><strong data-start=\"1967\" data-end=\"1990\">Admission Procedure</strong></span></h6><ul><li data-start=\"1991\" data-end=\"2232\">Fill out the online/offline application form</li><li data-start=\"1991\" data-end=\"2232\">Submit required documents (10th &amp; 12th marksheets, ID proof, photo)</li><li data-start=\"1991\" data-end=\"2232\">Pay admission/application fee</li><li data-start=\"1991\" data-end=\"2232\">Some colleges may conduct entrance exams</li><li data-start=\"1991\" data-end=\"2232\">Admission confirmation and enrollment</li></ul><p data-start=\"2234\" data-end=\"2315\">Admissions are generally open in <strong data-start=\"2267\" data-end=\"2280\">June–July</strong> and sometimes <strong data-start=\"2295\" data-end=\"2314\">January session</strong>.</p><hr><h6 data-section-id=\"1ex0xgy\" data-start=\"2322\" data-end=\"2348\"><span role=\"text\"><strong data-start=\"2325\" data-end=\"2348\">Top Specializations</strong></span></h6><ul><li data-start=\"2349\" data-end=\"2514\">B.Sc in Physics</li><li data-start=\"2349\" data-end=\"2514\">B.Sc in Chemistry</li><li data-start=\"2349\" data-end=\"2514\">B.Sc in Mathematics</li><li data-start=\"2349\" data-end=\"2514\">B.Sc in Biology</li><li data-start=\"2349\" data-end=\"2514\">B.Sc in Computer Science</li><li data-start=\"2349\" data-end=\"2514\">B.Sc in Biotechnology</li><li data-start=\"2349\" data-end=\"2514\">B.Sc in Microbiology</li></ul><hr><h6 data-section-id=\"e9yg3b\" data-start=\"2521\" data-end=\"2547\"><span role=\"text\"><strong data-start=\"2524\" data-end=\"2545\">Is B.Sc Worth It?</strong></span></h6><p data-start=\"2548\" data-end=\"2797\">Yes, pursuing a B.Sc is highly valuable for students interested in science and research. It builds strong analytical and problem-solving skills and provides a solid foundation for higher studies and professional careers in various scientific fields.</p><hr><h6 data-section-id=\"qz8v37\" data-start=\"2804\" data-end=\"2835\"><span role=\"text\"><strong data-start=\"2807\" data-end=\"2835\">Recognitions &amp; Approvals</strong></span></h6><p data-start=\"2836\" data-end=\"2900\">Before taking admission, ensure the university is approved by:</p><ul><li data-start=\"2901\" data-end=\"2988\">UGC (University Grants Commission)</li><li data-start=\"2901\" data-end=\"2988\">AICTE (if applicable)</li><li data-start=\"2901\" data-end=\"2988\">NAAC Accreditation</li></ul><p data-start=\"2990\" data-end=\"3085\">Degrees from recognized universities are valid for jobs and higher studies in India and abroad.</p><hr><h6 data-section-id=\"1cn1tx1\" data-start=\"3092\" data-end=\"3122\"><span role=\"text\"><strong data-start=\"3095\" data-end=\"3122\">Career Scope After B.Sc</strong></span></h6><h6 data-section-id=\"p64cbj\" data-start=\"3124\" data-end=\"3150\"><span role=\"text\"><strong data-start=\"3128\" data-end=\"3150\">Top Career Options</strong></span></h6><ul><li data-start=\"3151\" data-end=\"3277\">Research Scientist</li><li data-start=\"3151\" data-end=\"3277\">Lab Technician</li><li data-start=\"3151\" data-end=\"3277\">Data Analyst</li><li data-start=\"3151\" data-end=\"3277\">IT Professional</li><li data-start=\"3151\" data-end=\"3277\">Healthcare Assistant</li><li data-start=\"3151\" data-end=\"3277\">Teacher / Lecturer</li></ul><h6 data-section-id=\"1qmqpba\" data-start=\"3279\" data-end=\"3309\"><span role=\"text\"><strong data-start=\"3283\" data-end=\"3309\">Higher Studies Options</strong></span></h6><ul><li data-start=\"3310\" data-end=\"3379\">M.Sc (Master of Science)</li><li data-start=\"3310\" data-end=\"3379\">MBA</li><li data-start=\"3310\" data-end=\"3379\">MCA</li><li data-start=\"3310\" data-end=\"3379\">Professional Courses</li></ul><hr><h6 data-section-id=\"1pbivc6\" data-start=\"3386\" data-end=\"3405\"><span role=\"text\"><strong data-start=\"3389\" data-end=\"3403\">Conclusion</strong></span></h6><p data-start=\"3406\" data-end=\"3675\" data-is-last-node=\"\" data-is-only-node=\"\">The B.Sc program is an excellent choice for students who want to build a career in science and research. With practical learning, multiple specializations, and wide career opportunities, it provides a strong foundation for both higher education and professional growth.</p></div></div></div></div></div></div></section></div></div></div></div></main></div></div></div></div></div></div>', 'The Bachelor of Science (B.Sc) is an undergraduate program designed to build a strong foundation in scientific knowledge, research, and analytical skills. It focuses on subjects like Physics, Chemistry, Biology, Mathematics, and Computer Science, along with practical learning and laboratory work. The course duration is typically 3 years (6 semesters) and is suitable for students from a science background. Admission requires 10+2 with science stream from a recognized board. A B.Sc degree opens career opportunities in research, healthcare, IT, education, and also provides a pathway for higher studies like M.Sc, MBA, or professional courses.', 'general-bsc', 'The Bachelor of Science (B.Sc) is an undergraduate program designed to build a strong foundation in scientific knowledge, research, and analytical skills. It focuses on subjects like Physics, Chemistry, Biology, Mathematics, and Computer Science, along with practical learning and laboratory work. The course duration is typically 3 years (6 semesters) and is suitable for students from a science background. Admission requires 10+2 with science stream from a recognized board. A B.Sc degree opens career opportunities in research, healthcare, IT, education, and also provides a pathway for higher studies like M.Sc, MBA, or professional courses.', 'general-bsc', NULL, '1', '2026-04-13 07:55:59', '2026-04-17 11:05:36');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('4', '2', '4', '10th', 'High School', 'new-assets/img/courses/10th_banner.png', 'highschool', '1 Year', '9th pass from a recognized board', '₹10,000 – ₹45,000 per year', '<div class=\"relative basis-auto flex-col -mb-(--composer-overlap-px) pb-(--composer-overlap-px) [--composer-overlap-px:28px] grow flex\"><div class=\"flex flex-col text-sm pb-25\"><section class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:c77d5c3e-9a91-45b7-b8f4-bfc480df34db-23\" data-testid=\"conversation-turn-48\" data-scroll-anchor=\"true\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-message-author-role=\"assistant\" data-message-id=\"b9e21777-e32a-49e2-8bf9-7de30059378e\" dir=\"auto\" data-message-model-slug=\"gpt-5-3\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\"><h6 data-section-id=\"19wm21h\" data-start=\"79\" data-end=\"100\"><span role=\"text\"><strong data-start=\"82\" data-end=\"98\">About Course</strong></span></h6><p data-start=\"101\" data-end=\"465\">High School (10th) is a foundational academic level that plays a crucial role in shaping a student’s future. It focuses on building core knowledge in subjects like Mathematics, Science, Social Studies, and Languages. This stage helps students develop analytical thinking, problem-solving skills, and prepares them for higher secondary education and career choices.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"472\" data-end=\"491\"><span role=\"text\"><strong data-start=\"475\" data-end=\"491\">Key Features</strong></span></h6><ul><li data-start=\"492\" data-end=\"799\"><strong data-start=\"494\" data-end=\"504\">Level:</strong> Secondary Education</li><li data-start=\"492\" data-end=\"799\"><strong data-start=\"529\" data-end=\"542\">Duration:</strong> 1 Year (Class 10)</li><li data-start=\"492\" data-end=\"799\"><strong data-start=\"565\" data-end=\"583\">Mode of Study:</strong> Regular / Open Schooling</li><li data-start=\"492\" data-end=\"799\"><strong data-start=\"613\" data-end=\"623\">Board:</strong> CBSE, ICSE, State Boards, NIOS</li><li data-start=\"492\" data-end=\"799\"><strong data-start=\"659\" data-end=\"672\">Subjects:</strong> Mathematics, Science, Social Science, English, Hindi/Regional Language</li><li data-start=\"492\" data-end=\"799\"><strong data-start=\"748\" data-end=\"763\">Assessment:</strong> Internal Assessment + Board Exams</li></ul><hr><h6 data-section-id=\"rh3c0z\" data-start=\"806\" data-end=\"832\"><span role=\"text\"><strong data-start=\"809\" data-end=\"832\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"833\" data-end=\"908\">The curriculum focuses on academic development and practical understanding.</p><h6 data-section-id=\"1ogneya\" data-start=\"910\" data-end=\"931\"><span role=\"text\"><strong data-start=\"914\" data-end=\"931\">Core Subjects</strong></span></h6><ul><li data-start=\"932\" data-end=\"1097\">Mathematics</li><li data-start=\"932\" data-end=\"1097\">Science (Physics, Chemistry, Biology basics)</li><li data-start=\"932\" data-end=\"1097\">Social Science (History, Geography, Civics, Economics)</li><li data-start=\"932\" data-end=\"1097\">English</li><li data-start=\"932\" data-end=\"1097\">Hindi / Regional Language</li></ul><hr><h6 data-section-id=\"mm6aog\" data-start=\"1104\" data-end=\"1133\"><span role=\"text\"><strong data-start=\"1107\" data-end=\"1133\">Eligibility &amp; Duration</strong></span></h6><ul><li data-start=\"1134\" data-end=\"1258\"><strong data-start=\"1136\" data-end=\"1152\">Eligibility:</strong> 9th pass from a recognized school/board</li><li data-start=\"1134\" data-end=\"1258\"><strong data-start=\"1197\" data-end=\"1210\">Duration:</strong> 1 year</li><li data-start=\"1134\" data-end=\"1258\"><strong data-start=\"1222\" data-end=\"1236\">Age Limit:</strong> No strict age limit</li></ul><hr><h6 data-section-id=\"k2ojyd\" data-start=\"1265\" data-end=\"1290\"><span role=\"text\"><strong data-start=\"1268\" data-end=\"1290\">Importance of 10th</strong></span></h6><ul><li data-start=\"1291\" data-end=\"1438\">Builds strong academic foundation</li><li data-start=\"1291\" data-end=\"1438\">Helps in choosing stream (Science / Commerce / Arts)</li><li data-start=\"1291\" data-end=\"1438\">Important for future studies and career planning</li></ul><hr><h6 data-section-id=\"1ivh4s3\" data-start=\"1445\" data-end=\"1474\"><span role=\"text\"><strong data-start=\"1448\" data-end=\"1474\">Career Path After 10th</strong></span></h6><p data-start=\"1475\" data-end=\"1532\">After completing High School (10th), students can choose:</p><ul><li data-start=\"1533\" data-end=\"1625\">Science Stream</li><li data-start=\"1533\" data-end=\"1625\">Commerce Stream</li><li data-start=\"1533\" data-end=\"1625\">Arts/Humanities</li><li data-start=\"1533\" data-end=\"1625\">Diploma / Polytechnic Courses</li></ul><hr><h6 data-section-id=\"1pbivc6\" data-start=\"1632\" data-end=\"1651\"><span role=\"text\"><strong data-start=\"1635\" data-end=\"1649\">Conclusion</strong></span></h6><p data-start=\"1652\" data-end=\"1857\">High School (10th) is one of the most important stages in a student’s academic journey. It not only builds fundamental knowledge but also helps in deciding future career paths and higher education streams.</p></div></div></div></div></div></div></section></div></div>', 'High School (10th) is a crucial stage in a student’s academic journey that builds a strong foundation in core subjects like Mathematics, Science, Social Science, and Languages. It helps develop analytical thinking, problem-solving skills, and prepares students for higher secondary education. The course is usually of 1-year duration and is offered by boards like CBSE, ICSE, State Boards, and NIOS through regular or open schooling modes. Assessment includes internal evaluation and board examinations. After completing 10th, students can choose streams like Science, Commerce, or Arts, making it an important step for future career planning.', 'high-scool', 'High School (10th) is a crucial stage in a student’s academic journey that builds a strong foundation in core subjects like Mathematics, Science, Social Science, and Languages. It helps develop analytical thinking, problem-solving skills, and prepares students for higher secondary education. The course is usually of 1-year duration and is offered by boards like CBSE, ICSE, State Boards, and NIOS through regular or open schooling modes. Assessment includes internal evaluation and board examinations. After completing 10th, students can choose streams like Science, Commerce, or Arts, making it an important step for future career planning.', 'high-scool', NULL, '1', '2026-04-13 08:07:59', '2026-04-13 08:07:59');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('5', '4', '2', 'M.COM.', 'Master of Commerce', 'new-assets/img/courses/mcom_banner.png', 'mcom', '2 year', 'Commerce’s Degree in relevant Science discipline (B.COM or equivalent) from a recognized', '₹15,000 – ₹90,000 per year', '<h6 data-section-id=\"19wm21h\" data-start=\"124\" data-end=\"145\"><span role=\"text\"><strong data-start=\"127\" data-end=\"143\">About Course</strong></span></h6><p data-start=\"146\" data-end=\"594\">The Master of Commerce (M.Com) is a postgraduate degree program designed for students who want to gain advanced knowledge in commerce, accounting, finance, taxation, and business management. It is ideal for graduates who wish to build expertise in financial analysis, corporate management, and research. The program focuses on theoretical concepts along with practical applications to prepare students for professional roles in the corporate world.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"601\" data-end=\"620\"><span role=\"text\"><strong data-start=\"604\" data-end=\"620\">Key Features</strong></span></h6><div class=\"TyagGW_tableContainer\"><div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\"><figure class=\"table\"><table><thead><tr><th><strong>Details</strong></th><th>&nbsp;</th></tr></thead><tbody><tr><td><strong>Programme Title</strong></td><td>Master of Commerce</td></tr><tr><td><strong>Level</strong></td><td>Postgraduate</td></tr><tr><td><strong>Duration</strong></td><td>2 Years (4 Semesters)</td></tr><tr><td><strong>Mode of Study</strong></td><td>Regular / Online / Distance</td></tr><tr><td><strong>Affiliation</strong></td><td>UGC, AICTE, NAAC (as per university)</td></tr><tr><td><strong>Eligibility Criteria</strong></td><td>Graduation (B.Com or equivalent) with minimum 45–50% marks</td></tr><tr><td><strong>Core Subjects</strong></td><td>Accounting, Finance, Taxation, Economics, Business Management</td></tr><tr><td><strong>Average Fees</strong></td><td>₹20,000 – ₹1,00,000 per year</td></tr><tr><td><strong>Assessment &amp; Evaluation</strong></td><td>Internal Assessment + Semester Exams</td></tr><tr><td><strong>Specialisations</strong></td><td>Finance, Accounting, Banking, Taxation, International Business</td></tr></tbody></table></figure></div></div><p>&nbsp;</p><h6 data-section-id=\"g1fqn7\" data-start=\"1278\" data-end=\"1306\"><span role=\"text\"><strong data-start=\"1281\" data-end=\"1304\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"1307\" data-end=\"1391\">The M.Com curriculum focuses on advanced commerce, finance, and management concepts.</p><h6 data-section-id=\"1ogneya\" data-start=\"1393\" data-end=\"1414\"><span role=\"text\"><strong data-start=\"1397\" data-end=\"1414\">Core Subjects</strong></span></h6><ul><li data-start=\"1415\" data-end=\"1627\">Advanced Financial Accounting</li><li data-start=\"1415\" data-end=\"1627\">Corporate Finance</li><li data-start=\"1415\" data-end=\"1627\">Business Economics</li><li data-start=\"1415\" data-end=\"1627\">Cost &amp; Management Accounting</li><li data-start=\"1415\" data-end=\"1627\">Income Tax &amp; GST</li><li data-start=\"1415\" data-end=\"1627\">Auditing &amp; Assurance</li><li data-start=\"1415\" data-end=\"1627\">Financial Management</li><li data-start=\"1415\" data-end=\"1627\">Business Research Methods</li></ul><h6 data-section-id=\"1tnkfuw\" data-start=\"1629\" data-end=\"1671\"><span role=\"text\"><strong data-start=\"1633\" data-end=\"1671\">Elective / Specialization Subjects</strong></span></h6><ul><li data-start=\"1672\" data-end=\"1813\">Banking &amp; Insurance</li><li data-start=\"1672\" data-end=\"1813\">International Business</li><li data-start=\"1672\" data-end=\"1813\">Financial Markets</li><li data-start=\"1672\" data-end=\"1813\">Investment Analysis</li><li data-start=\"1672\" data-end=\"1813\">E-Commerce</li><li data-start=\"1672\" data-end=\"1813\">Human Resource Management</li></ul><hr><h6 data-section-id=\"mm6aog\" data-start=\"1820\" data-end=\"1849\"><span role=\"text\"><strong data-start=\"1823\" data-end=\"1849\">Eligibility &amp; Duration</strong></span></h6><ul><li data-start=\"1850\" data-end=\"2074\"><strong data-start=\"1852\" data-end=\"1868\">Eligibility:</strong> Graduation (B.Com or equivalent) from a recognized university</li><li data-start=\"1850\" data-end=\"2074\"><strong data-start=\"1935\" data-end=\"1956\">Minimum Duration:</strong> 2 years (4 semesters)</li><li data-start=\"1850\" data-end=\"2074\"><strong data-start=\"1983\" data-end=\"2004\">Maximum Duration:</strong> 4–5 years (depending on university)</li><li data-start=\"1850\" data-end=\"2074\"><strong data-start=\"2045\" data-end=\"2059\">Age Limit:</strong> No age limit</li></ul><hr><h6 data-section-id=\"12q771d\" data-start=\"2081\" data-end=\"2107\"><span role=\"text\"><strong data-start=\"2084\" data-end=\"2107\">Admission Procedure</strong></span></h6><ul><li data-start=\"2108\" data-end=\"2368\">Fill out the application form (online/offline)</li><li data-start=\"2108\" data-end=\"2368\">Submit required documents (Graduation marksheets, ID proof, photo)</li><li data-start=\"2108\" data-end=\"2368\">Pay admission/application fee</li><li data-start=\"2108\" data-end=\"2368\">Some universities may conduct entrance exams or interviews</li><li data-start=\"2108\" data-end=\"2368\">Admission confirmation and enrollment</li></ul><p data-start=\"2370\" data-end=\"2451\">Admissions are generally open in <strong data-start=\"2403\" data-end=\"2416\">June–July</strong> and sometimes <strong data-start=\"2431\" data-end=\"2450\">January session</strong>.</p><hr><h6 data-section-id=\"1ex0xgy\" data-start=\"2458\" data-end=\"2484\"><span role=\"text\"><strong data-start=\"2461\" data-end=\"2484\">Top Specializations</strong></span></h6><ul><li data-start=\"2485\" data-end=\"2651\">M.Com in Finance</li><li data-start=\"2485\" data-end=\"2651\">M.Com in Accounting</li><li data-start=\"2485\" data-end=\"2651\">M.Com in Banking &amp; Insurance</li><li data-start=\"2485\" data-end=\"2651\">M.Com in Taxation</li><li data-start=\"2485\" data-end=\"2651\">M.Com in International Business</li><li data-start=\"2485\" data-end=\"2651\">M.Com in Financial Markets</li></ul><hr><h6 data-section-id=\"14kb06h\" data-start=\"2658\" data-end=\"2685\"><span role=\"text\"><strong data-start=\"2661\" data-end=\"2683\">Is M.Com Worth It?</strong></span></h6><p data-start=\"2686\" data-end=\"2932\">Yes, pursuing an M.Com is highly beneficial for students who want to build a career in finance, accounting, and business management. It enhances subject expertise, analytical skills, and opens doors to higher-level job roles and academic careers.</p><hr><h6 data-section-id=\"qz8v37\" data-start=\"2939\" data-end=\"2970\"><span role=\"text\"><strong data-start=\"2942\" data-end=\"2970\">Recognitions &amp; Approvals</strong></span></h6><p data-start=\"2971\" data-end=\"3035\">Before taking admission, ensure the university is approved by:</p><ul><li data-start=\"3036\" data-end=\"3123\">UGC (University Grants Commission)</li><li data-start=\"3036\" data-end=\"3123\">AICTE (if applicable)</li><li data-start=\"3036\" data-end=\"3123\">NAAC Accreditation</li></ul><p data-start=\"3125\" data-end=\"3255\">Degrees from recognized universities are valid for government and private jobs, as well as for higher studies in India and abroad.</p><hr><h6 data-section-id=\"vkajv\" data-start=\"3262\" data-end=\"3293\"><span role=\"text\"><strong data-start=\"3265\" data-end=\"3293\">Career Scope After M.Com</strong></span></h6><h6 data-section-id=\"p64cbj\" data-start=\"3295\" data-end=\"3321\"><span role=\"text\"><strong data-start=\"3299\" data-end=\"3321\">Top Career Options</strong></span></h6><ul><li data-start=\"3322\" data-end=\"3501\">Accountant / Senior Accountant</li><li data-start=\"3322\" data-end=\"3501\">Financial Analyst</li><li data-start=\"3322\" data-end=\"3501\">Auditor / Tax Consultant</li><li data-start=\"3322\" data-end=\"3501\">Banking Professional</li><li data-start=\"3322\" data-end=\"3501\">Investment Advisor</li><li data-start=\"3322\" data-end=\"3501\">Business Analyst</li><li data-start=\"3322\" data-end=\"3501\">Lecturer / Professor</li></ul><h6 data-section-id=\"1qmqpba\" data-start=\"3503\" data-end=\"3533\"><span role=\"text\"><strong data-start=\"3507\" data-end=\"3533\">Higher Studies Options</strong></span></h6><ul><li data-start=\"3534\" data-end=\"3649\">Ph.D. (Doctor of Philosophy)</li><li data-start=\"3534\" data-end=\"3649\">MBA (Master of Business Administration)</li><li data-start=\"3534\" data-end=\"3649\">Professional Courses (CA, CS, CMA)</li></ul><hr><h6 data-section-id=\"1pbivc6\" data-start=\"3656\" data-end=\"3675\"><span role=\"text\"><strong data-start=\"3659\" data-end=\"3673\">Conclusion</strong></span></h6><p data-start=\"3676\" data-end=\"3972\" data-is-last-node=\"\" data-is-only-node=\"\">The M.Com program is an excellent choice for students aiming to build a strong career in commerce, finance, and business management. With advanced knowledge, multiple specializations, and wide career opportunities, it provides a solid foundation for both professional growth and higher education.</p>', 'The Master of Commerce (M.Com) is a postgraduate degree program designed for students who want to gain advanced knowledge in commerce, finance, accounting, and business management. It focuses on developing analytical, managerial, and research skills required for higher-level roles in the corporate and financial sectors. The course is typically of 2 years duration (4 semesters) and is open to graduates, especially those from a commerce background such as B.Com or equivalent.', 'mcom', 'The Master of Commerce (M.Com) is a postgraduate degree program designed for students who want to gain advanced knowledge in commerce, finance, accounting, and business management. It focuses on developing analytical, managerial, and research skills required for higher-level roles in the corporate and financial sectors. The course is typically of 2 years duration (4 semesters) and is open to graduates, especially those from a commerce background such as B.Com or equivalent.', 'mcom', NULL, '1', '2026-04-13 08:21:27', '2026-04-13 11:38:59');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('6', '2', '4', '12th', '12th (Senior Secondary Education – 10+2)', 'new-assets/img/courses/12th_banner.png', 'senior-secondary', '2 Years (Class 11 & 12)', 'Passed Class 10 from a recognized board', '0', '<h6 data-section-id=\"2ll4ot\" data-start=\"428\" data-end=\"451\"><span role=\"text\"><strong data-start=\"435\" data-end=\"451\">About Course</strong></span></h6><p data-start=\"452\" data-end=\"715\">Senior Secondary (10+2) is an advanced level of education that allows students to specialize in their chosen stream. It helps in developing in-depth subject knowledge, critical thinking, and essential skills required for higher education and professional careers.</p><hr><h6 data-section-id=\"bfokhy\" data-start=\"722\" data-end=\"744\"><span role=\"text\"><strong data-start=\"728\" data-end=\"744\">Key Features</strong></span></h6><ul><li data-start=\"745\" data-end=\"1028\"><strong data-start=\"747\" data-end=\"757\">Level:</strong> Senior Secondary (10+2)</li><li data-start=\"745\" data-end=\"1028\"><strong data-start=\"786\" data-end=\"799\">Duration:</strong> 2 Years (Class 11 &amp; 12)</li><li data-start=\"745\" data-end=\"1028\"><strong data-start=\"828\" data-end=\"846\">Mode of Study:</strong> Regular / Open Schooling</li><li data-start=\"745\" data-end=\"1028\"><strong data-start=\"876\" data-end=\"887\">Boards:</strong> CBSE, ICSE, State Boards, NIOS</li><li data-start=\"745\" data-end=\"1028\"><strong data-start=\"923\" data-end=\"935\">Streams:</strong> Science, Commerce, Arts / Humanities</li><li data-start=\"745\" data-end=\"1028\"><strong data-start=\"977\" data-end=\"992\">Assessment:</strong> Internal Evaluation + Board Exams</li></ul><hr><h6 data-section-id=\"1ofcux3\" data-start=\"1035\" data-end=\"1065\"><span role=\"text\"><strong data-start=\"1042\" data-end=\"1065\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"1066\" data-end=\"1170\">The curriculum is designed based on the selected stream with a balance of theory and practical learning.</p><h6 data-start=\"1172\" data-end=\"1198\"><span role=\"text\"><strong data-start=\"1180\" data-end=\"1198\">Science Stream</strong></span></h6><ul><li data-start=\"1199\" data-end=\"1283\">Physics</li><li data-start=\"1199\" data-end=\"1283\">Chemistry</li><li data-start=\"1199\" data-end=\"1283\">Mathematics / Biology</li><li data-start=\"1199\" data-end=\"1283\">English</li><li data-start=\"1199\" data-end=\"1283\">Optional Subject</li></ul><h6 data-start=\"1285\" data-end=\"1312\"><span role=\"text\"><strong data-start=\"1293\" data-end=\"1312\">Commerce Stream</strong></span></h6><ul><li data-start=\"1313\" data-end=\"1415\">Accountancy</li><li data-start=\"1313\" data-end=\"1415\">Business Studies</li><li data-start=\"1313\" data-end=\"1415\">Economics</li><li data-start=\"1313\" data-end=\"1415\">Mathematics / Informatics Practices</li><li data-start=\"1313\" data-end=\"1415\">English</li></ul><h6 data-start=\"1417\" data-end=\"1446\"><span role=\"text\"><strong data-start=\"1425\" data-end=\"1446\">Arts / Humanities</strong></span></h6><ul><li data-start=\"1447\" data-end=\"1553\">History</li><li data-start=\"1447\" data-end=\"1553\">Geography</li><li data-start=\"1447\" data-end=\"1553\">Political Science</li><li data-start=\"1447\" data-end=\"1553\">Sociology / Psychology</li><li data-start=\"1447\" data-end=\"1553\">English / Regional Language</li></ul><hr><h6 data-section-id=\"zglzue\" data-start=\"1560\" data-end=\"1592\"><span role=\"text\"><strong data-start=\"1566\" data-end=\"1592\">Eligibility &amp; Duration</strong></span></h6><ul><li data-start=\"1593\" data-end=\"1718\"><strong data-start=\"1595\" data-end=\"1611\">Eligibility:</strong> Passed Class 10 from a recognized board</li><li data-start=\"1593\" data-end=\"1718\"><strong data-start=\"1656\" data-end=\"1669\">Duration:</strong> 2 Years</li><li data-start=\"1593\" data-end=\"1718\"><strong data-start=\"1682\" data-end=\"1696\">Age Limit:</strong> No strict age limit</li></ul><hr><h6 data-section-id=\"v5d4y8\" data-start=\"1725\" data-end=\"1766\"><span role=\"text\"><strong data-start=\"1732\" data-end=\"1766\">Importance of Senior Secondary</strong></span></h6><ul><li data-start=\"1767\" data-end=\"1945\">Builds strong subject specialization</li><li data-start=\"1767\" data-end=\"1945\">Helps in choosing career direction</li><li data-start=\"1767\" data-end=\"1945\">Required for higher education (College/University)</li><li data-start=\"1767\" data-end=\"1945\">Prepares students for competitive exams</li></ul><hr><h6 data-section-id=\"rhsht2\" data-start=\"1952\" data-end=\"1985\"><span role=\"text\"><strong data-start=\"1959\" data-end=\"1985\">Career Path After 10+2</strong></span></h6><p data-start=\"1986\" data-end=\"2041\">After completing Senior Secondary, students can choose:</p><ul><li data-start=\"2042\" data-end=\"2247\">Graduation (B.A / B.Sc / B.Com)</li><li data-start=\"2042\" data-end=\"2247\">Professional Courses (Engineering, Medical, Management, etc.)</li><li data-start=\"2042\" data-end=\"2247\">&nbsp;Diploma &amp; Skill-Based Courses</li><li data-start=\"2042\" data-end=\"2247\">Competitive Exams (Government Jobs, Entrance Tests)</li></ul><hr><h6 data-section-id=\"6k504\" data-start=\"2254\" data-end=\"2275\"><span role=\"text\"><strong data-start=\"2261\" data-end=\"2275\">Conclusion</strong></span></h6><p data-start=\"2276\" data-end=\"2486\">Senior Secondary (10+2) is a crucial stage in a student’s academic journey. It provides deep subject knowledge, career direction, and a strong foundation for higher education and long-term professional success.</p>', 'Senior Secondary Education builds a strong academic foundation for higher studies and career growth. It focuses on skill development, subject expertise, and preparing students for future opportunities.', 'senior-secondary', 'Senior Secondary Education builds a strong academic foundation for higher studies and career growth. It focuses on skill development, subject expertise, and preparing students for future opportunities.', 'senior-secondary', NULL, '1', '2026-04-17 11:20:45', '2026-04-17 11:20:45');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('7', '3', '1', 'BCA', 'Bachelor of Computer Applications', 'new-assets/img/courses/bca_banner.png', 'bca', '3 Years (6 Semesters)', '10+2 from a recognized board', '₹10,000 – ₹30,000 per semester', '<p data-start=\"437\" data-end=\"768\">Bachelor of Computer Applications (BCA) is designed to equip students with essential knowledge of computer science and applications. The course focuses on practical and theoretical learning in areas like programming, web development, database management, and software engineering, preparing students for careers in the IT industry.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"775\" data-end=\"794\"><span role=\"text\"><strong data-start=\"778\" data-end=\"794\">Key Features</strong></span></h6><p data-start=\"796\" data-end=\"853\"><strong data-start=\"796\" data-end=\"815\">Programme Title</strong><br>Bachelor of Computer Applications</p><p data-start=\"855\" data-end=\"882\"><strong data-start=\"855\" data-end=\"864\">Level</strong><br>Undergraduate</p><p data-start=\"884\" data-end=\"922\"><strong data-start=\"884\" data-end=\"896\">Duration</strong><br>3 Years (6 Semesters)</p><p data-start=\"924\" data-end=\"962\"><strong data-start=\"924\" data-end=\"941\">Mode of Study</strong><br>Online / Regular</p><p data-start=\"964\" data-end=\"1013\"><strong data-start=\"964\" data-end=\"979\">Affiliation</strong><br>UGC-DEB, AICTE, NAAC, and AIU</p><p data-start=\"1015\" data-end=\"1135\"><strong data-start=\"1015\" data-end=\"1039\">Eligibility Criteria</strong><br>10+2 from a recognized board (Mathematics preferred but not mandatory in many universities)</p><p data-start=\"1137\" data-end=\"1318\"><strong data-start=\"1137\" data-end=\"1156\">Common Subjects</strong><br>Programming in C, C++, Java, Database Management Systems (DBMS), Web Development, Software Engineering, Data Structures, Computer Networks, Operating Systems</p><p data-start=\"1320\" data-end=\"1395\"><strong data-start=\"1320\" data-end=\"1336\">Average Fees</strong><br>₹10,000 – ₹30,000 per semester (varies by institution)</p><p data-start=\"1397\" data-end=\"1475\"><strong data-start=\"1397\" data-end=\"1424\">Assessment &amp; Evaluation</strong><br>Assignments + Practical Exams + Semester Exams</p><p data-start=\"1477\" data-end=\"1593\"><strong data-start=\"1477\" data-end=\"1496\">Specialisations</strong><br>Data Science, Artificial Intelligence, Cyber Security, Cloud Computing, Software Development</p><hr><h6 data-section-id=\"1bgdrvf\" data-start=\"1600\" data-end=\"1628\"><span role=\"text\"><strong data-start=\"1604\" data-end=\"1628\">Career Opportunities</strong></span></h6><ul><li data-start=\"1629\" data-end=\"1755\">Software Developer</li><li data-start=\"1629\" data-end=\"1755\">Web Developer</li><li data-start=\"1629\" data-end=\"1755\">Data Analyst</li><li data-start=\"1629\" data-end=\"1755\">System Administrator</li><li data-start=\"1629\" data-end=\"1755\">IT Support Specialist</li><li data-start=\"1629\" data-end=\"1755\">App Developer</li></ul><hr><h6 data-section-id=\"1i9ix39\" data-start=\"1762\" data-end=\"1782\"><span role=\"text\"><strong data-start=\"1766\" data-end=\"1780\">Conclusion</strong></span></h6><p data-start=\"1783\" data-end=\"1984\">BCA is an excellent choice for students interested in the IT field. It offers strong technical skills, career opportunities in software and technology, and a pathway for higher studies like MCA or MBA.</p>', 'BCA is a popular undergraduate program focused on computer applications, software development, and IT skills. It provides a strong foundation in programming, databases, networking, and modern technologies.', 'bca', 'BCA is a popular undergraduate program focused on computer applications, software development, and IT skills. It provides a strong foundation in programming, databases, networking, and modern technologies.', 'bca', NULL, '1', '2026-04-17 11:45:45', '2026-04-17 11:45:45');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('8', '4', '2', 'M.A.', 'Master of Arts', 'new-assets/img/courses/ma_banner.png', 'ma', '2 Years (4 Semesters)', 'Bachelor’s Degree in any relevant discipline from a recognized university', '₹8,000 – ₹25,000 per semester', '<p data-start=\"295\" data-end=\"566\">M.A is designed for students who want to specialize in a particular subject after graduation. The course enhances critical thinking, communication skills, and in-depth understanding of the chosen field, preparing students for academic, professional, and research careers.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"573\" data-end=\"592\"><span role=\"text\"><strong data-start=\"576\" data-end=\"592\">Key Features</strong></span></h6><p data-start=\"594\" data-end=\"632\"><strong data-start=\"594\" data-end=\"613\">Programme Title</strong><br>Master of Arts</p><p data-start=\"634\" data-end=\"660\"><strong data-start=\"634\" data-end=\"643\">Level</strong><br>Postgraduate</p><p data-start=\"662\" data-end=\"700\"><strong data-start=\"662\" data-end=\"674\">Duration</strong><br>2 Years (4 Semesters)</p><p data-start=\"702\" data-end=\"740\"><strong data-start=\"702\" data-end=\"719\">Mode of Study</strong><br>Online / Regular</p><p data-start=\"742\" data-end=\"780\"><strong data-start=\"742\" data-end=\"757\">Affiliation</strong><br>UGC-DEB, NAAC, AIU</p><p data-start=\"782\" data-end=\"884\"><strong data-start=\"782\" data-end=\"806\">Eligibility Criteria</strong><br>Bachelor’s Degree in any relevant discipline from a recognized university</p><p data-start=\"886\" data-end=\"1013\"><strong data-start=\"886\" data-end=\"905\">Common Subjects</strong><br>English, History, Political Science, Sociology, Psychology, Economics, Public Administration, Geography</p><p data-start=\"1015\" data-end=\"1065\"><strong data-start=\"1015\" data-end=\"1031\">Average Fees</strong><br>₹8,000 – ₹25,000 per semester</p><p data-start=\"1067\" data-end=\"1142\"><strong data-start=\"1067\" data-end=\"1094\">Assessment &amp; Evaluation</strong><br>Assignments + Semester Exams + Project Work</p><p data-start=\"1144\" data-end=\"1244\"><strong data-start=\"1144\" data-end=\"1163\">Specialisations</strong><br>English, Hindi, History, Political Science, Sociology, Psychology, Economics</p><hr><h6 data-section-id=\"1bgdrvf\" data-start=\"1251\" data-end=\"1279\"><span role=\"text\"><strong data-start=\"1255\" data-end=\"1279\">Career Opportunities</strong></span></h6><ul><li data-start=\"1280\" data-end=\"1406\">Lecturer / Teacher</li><li data-start=\"1280\" data-end=\"1406\">Content Writer</li><li data-start=\"1280\" data-end=\"1406\">Civil Services Preparation</li><li data-start=\"1280\" data-end=\"1406\">Social Worker</li><li data-start=\"1280\" data-end=\"1406\">Research Analyst</li><li data-start=\"1280\" data-end=\"1406\">Journalist</li></ul><hr><h6 data-section-id=\"1i9ix39\" data-start=\"1413\" data-end=\"1433\"><span role=\"text\"><strong data-start=\"1417\" data-end=\"1431\">Conclusion</strong></span></h6><p data-start=\"1434\" data-end=\"1607\">M.A is ideal for students who want to gain expertise in arts and humanities. It opens opportunities in education, research, government jobs, and various professional fields.</p>', 'Master of Arts (M.A) is a postgraduate degree that focuses on advanced knowledge in humanities, social sciences, and liberal arts. It helps students develop analytical thinking, research skills, and subject expertise.', 'master-of-arts', 'Master of Arts (M.A) is a postgraduate degree that focuses on advanced knowledge in humanities, social sciences, and liberal arts. It helps students develop analytical thinking, research skills, and subject expertise.', 'master-of-arts', NULL, '1', '2026-04-17 11:52:31', '2026-04-17 11:52:31');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('9', '4', '2', 'M.Sc.', 'Master of Science', 'new-assets/img/courses/msc_banner.png', 'msc', '2 Years (4 Semesters)', 'Bachelor’s degree (B.Sc or equivalent) from a recognized university', '₹9,000 – ₹11,000 per semester', '<p data-start=\"160\" data-end=\"651\">The Master of Science (M.Sc) program is a postgraduate degree designed for students who want to gain advanced knowledge and specialization in science and technical subjects. It is ideal for students aiming to build careers in research, education, technology, healthcare, and scientific industries. The program focuses on theoretical understanding, practical applications, laboratory work, research projects, and analytical skills to prepare students for professional and academic excellence.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"658\" data-end=\"677\"><span role=\"text\"><strong data-start=\"661\" data-end=\"677\">Key Features</strong></span></h6><p data-start=\"679\" data-end=\"720\"><strong data-start=\"679\" data-end=\"698\">Programme Title</strong><br>Master of Science</p><p data-start=\"722\" data-end=\"748\"><strong data-start=\"722\" data-end=\"731\">Level</strong><br>Postgraduate</p><p data-start=\"750\" data-end=\"788\"><strong data-start=\"750\" data-end=\"762\">Duration</strong><br>2 Years (4 Semesters)</p><p data-start=\"790\" data-end=\"839\"><strong data-start=\"790\" data-end=\"807\">Mode of Study</strong><br>Regular / Online / Distance</p><p data-start=\"841\" data-end=\"897\"><strong data-start=\"841\" data-end=\"856\">Affiliation</strong><br>UGC, AICTE, NAAC (as per university)</p><p data-start=\"899\" data-end=\"995\"><strong data-start=\"899\" data-end=\"923\">Eligibility Criteria</strong><br>Bachelor’s degree (B.Sc or equivalent) from a recognized university</p><p data-start=\"997\" data-end=\"1112\"><strong data-start=\"997\" data-end=\"1014\">Core Subjects</strong><br>Physics, Chemistry, Mathematics, Biology, Computer Science, Environmental Science, Statistics</p><p data-start=\"1114\" data-end=\"1165\"><strong data-start=\"1114\" data-end=\"1130\">Average Fees</strong><br>₹15,000 – ₹50,000 per semester</p><p data-start=\"1167\" data-end=\"1253\"><strong data-start=\"1167\" data-end=\"1194\">Assessment &amp; Evaluation</strong><br>Internal Assessment + Practical Exams + Semester Exams</p><p data-start=\"1255\" data-end=\"1380\"><strong data-start=\"1255\" data-end=\"1274\">Specialisations</strong><br>Physics, Chemistry, Mathematics, Computer Science, Biotechnology, Microbiology, Environmental Science</p><hr><h6 data-section-id=\"rh3c0z\" data-start=\"1387\" data-end=\"1413\"><span role=\"text\"><strong data-start=\"1390\" data-end=\"1413\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"1415\" data-end=\"1521\">The M.Sc curriculum focuses on advanced scientific knowledge, research skills, and practical applications.</p><h6 data-section-id=\"1ogneya\" data-start=\"1523\" data-end=\"1544\"><span role=\"text\"><strong data-start=\"1527\" data-end=\"1544\">Core Subjects</strong></span></h6><ul><li data-start=\"1545\" data-end=\"1803\">Advanced Mathematics / Applied Mathematics</li><li data-start=\"1545\" data-end=\"1803\">Quantum Mechanics / Physics Concepts</li><li data-start=\"1545\" data-end=\"1803\">Organic &amp; Inorganic Chemistry</li><li data-start=\"1545\" data-end=\"1803\">Data Structures &amp; Algorithms</li><li data-start=\"1545\" data-end=\"1803\">Cell Biology &amp; Genetics</li><li data-start=\"1545\" data-end=\"1803\">Environmental Studies</li><li data-start=\"1545\" data-end=\"1803\">Research Methodology</li><li data-start=\"1545\" data-end=\"1803\">Statistical Analysis</li></ul><h6 data-section-id=\"1tnkfuw\" data-start=\"1805\" data-end=\"1847\"><span role=\"text\"><strong data-start=\"1809\" data-end=\"1847\">Elective / Specialization Subjects</strong></span></h6><ul><li data-start=\"1848\" data-end=\"1996\">Artificial Intelligence</li><li data-start=\"1848\" data-end=\"1996\">Data Science</li><li data-start=\"1848\" data-end=\"1996\">Biotechnology</li><li data-start=\"1848\" data-end=\"1996\">Nanotechnology</li><li data-start=\"1848\" data-end=\"1996\">Cyber Security</li><li data-start=\"1848\" data-end=\"1996\">Environmental Management</li><li data-start=\"1848\" data-end=\"1996\">Bioinformatics</li></ul><hr><h6 data-section-id=\"mm6aog\" data-start=\"2003\" data-end=\"2032\"><span role=\"text\"><strong data-start=\"2006\" data-end=\"2032\">Eligibility &amp; Duration</strong></span></h6><p data-start=\"2034\" data-end=\"2254\"><strong data-start=\"2034\" data-end=\"2050\">Eligibility:</strong> Bachelor’s degree (B.Sc or equivalent) from a recognized university<br><strong data-start=\"2121\" data-end=\"2142\">Minimum Duration:</strong> 2 years (4 semesters)<br><strong data-start=\"2167\" data-end=\"2188\">Maximum Duration:</strong> 4 years (depending on university)<br><strong data-start=\"2225\" data-end=\"2239\">Age Limit:</strong> No age limit</p><hr><h6 data-section-id=\"12q771d\" data-start=\"2261\" data-end=\"2287\"><span role=\"text\"><strong data-start=\"2264\" data-end=\"2287\">Admission Procedure</strong></span></h6><ul><li data-start=\"2289\" data-end=\"2547\">Fill out the online/offline application form</li><li data-start=\"2289\" data-end=\"2547\">Submit required documents (graduation marksheets, ID proof, photo)</li><li data-start=\"2289\" data-end=\"2547\">Pay application/admission fee</li><li data-start=\"2289\" data-end=\"2547\">Some universities may conduct entrance exams or interviews</li><li data-start=\"2289\" data-end=\"2547\">Admission confirmation and enrollment</li></ul><p data-start=\"2549\" data-end=\"2622\">Admissions are generally open in June–July and sometimes January session.</p><hr><h6 data-section-id=\"1ex0xgy\" data-start=\"2629\" data-end=\"2655\"><span role=\"text\"><strong data-start=\"2632\" data-end=\"2655\">Top Specializations</strong></span></h6><ul><li data-start=\"2657\" data-end=\"2836\">M.Sc in Physics</li><li data-start=\"2657\" data-end=\"2836\">M.Sc in Chemistry</li><li data-start=\"2657\" data-end=\"2836\">M.Sc in Mathematics</li><li data-start=\"2657\" data-end=\"2836\">M.Sc in Computer Science</li><li data-start=\"2657\" data-end=\"2836\">M.Sc in Biotechnology</li><li data-start=\"2657\" data-end=\"2836\">M.Sc in Microbiology</li><li data-start=\"2657\" data-end=\"2836\">M.Sc in Environmental Science</li></ul><hr><h6 data-section-id=\"1d9jxso\" data-start=\"2843\" data-end=\"2867\"><span role=\"text\"><strong data-start=\"2846\" data-end=\"2867\">Is M.Sc Worth It?</strong></span></h6><p data-start=\"2869\" data-end=\"3177\">Yes, pursuing an M.Sc is highly beneficial for students who want to build careers in science, research, and technology. It provides deep subject knowledge, research opportunities, and better career prospects in both private and government sectors. It is also a strong foundation for Ph.D. and higher studies.</p><hr><h6 data-section-id=\"qz8v37\" data-start=\"3184\" data-end=\"3215\"><span role=\"text\"><strong data-start=\"3187\" data-end=\"3215\">Recognitions &amp; Approvals</strong></span></h6><p data-start=\"3217\" data-end=\"3279\">Before taking admission, ensure the university is approved by:</p><ul><li data-start=\"3281\" data-end=\"3368\">UGC (University Grants Commission)</li><li data-start=\"3281\" data-end=\"3368\">AICTE (if applicable)</li><li data-start=\"3281\" data-end=\"3368\">NAAC Accreditation</li></ul><p data-start=\"3370\" data-end=\"3465\">Degrees from recognized universities are valid for jobs and higher studies in India and abroad.</p><hr><h6 data-section-id=\"1732fkq\" data-start=\"3472\" data-end=\"3502\"><span role=\"text\"><strong data-start=\"3475\" data-end=\"3502\">Career Scope After M.Sc</strong></span></h6><h6 data-section-id=\"p64cbj\" data-start=\"3504\" data-end=\"3530\"><span role=\"text\"><strong data-start=\"3508\" data-end=\"3530\">Top Career Options</strong></span></h6><ul><li data-start=\"3531\" data-end=\"3708\">Research Scientist</li><li data-start=\"3531\" data-end=\"3708\">Lecturer / Professor</li><li data-start=\"3531\" data-end=\"3708\">Data Analyst</li><li data-start=\"3531\" data-end=\"3708\">Lab Technician</li><li data-start=\"3531\" data-end=\"3708\">Scientist / Analyst</li><li data-start=\"3531\" data-end=\"3708\">Environmental Consultant</li><li data-start=\"3531\" data-end=\"3708\">Software Developer (for CS students)</li></ul><h6 data-section-id=\"1qmqpba\" data-start=\"3710\" data-end=\"3740\"><span role=\"text\"><strong data-start=\"3714\" data-end=\"3740\">Higher Studies Options</strong></span></h6><ul><li data-start=\"3741\" data-end=\"3866\">Ph.D. (Doctor of Philosophy)</li><li data-start=\"3741\" data-end=\"3866\">M.Phil (where applicable)</li><li data-start=\"3741\" data-end=\"3866\">Professional Certifications</li><li data-start=\"3741\" data-end=\"3866\">MBA (for management roles)</li></ul><hr><h6 data-section-id=\"9dt57q\" data-start=\"3873\" data-end=\"3890\"><span role=\"text\"><strong data-start=\"3876\" data-end=\"3890\">Conclusion</strong></span></h6><p data-start=\"3892\" data-end=\"4246\">The M.Sc program is an excellent choice for students aiming for specialization in science and research. With strong academic depth, practical exposure, and diverse career opportunities, it provides a solid platform for both professional careers and higher education. Choosing a recognized university ensures quality education and long-term career growth.</p>', 'M.Sc program is an excellent choice for students aiming for specialization in science and research. With strong academic depth, practical exposure, and diverse career opportunities, it provides a solid platform for both professional careers and higher education. Choosing a recognized university ensures quality education and long-term career growth.', 'master-of-science', 'M.Sc program is an excellent choice for students aiming for specialization in science and research. With strong academic depth, practical exposure, and diverse career opportunities, it provides a solid platform for both professional careers and higher education. Choosing a recognized university ensures quality education and long-term career growth.', 'master-of-science', NULL, '1', '2026-04-17 12:09:39', '2026-04-17 12:09:39');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('10', '4', '2', 'MBA', 'Master of Business Administration', 'new-assets/img/courses/mba_banner.png', 'gcc-mba', '2 Years (4 Semesters)', 'Graduation in any discipline from a recognized university', '₹25,000 – ₹1,00,000 per semester', '<p data-start=\"468\" data-end=\"866\">The Master of Business Administration (MBA) program is designed for students who want to build strong management, leadership, and business skills. It focuses on practical learning, case studies, real-world projects, and industry exposure. The course helps students develop problem-solving abilities, communication skills, and business strategies required for corporate success and entrepreneurship.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"873\" data-end=\"892\"><span role=\"text\"><strong data-start=\"876\" data-end=\"892\">Key Features</strong></span></h6><p data-start=\"894\" data-end=\"1578\"><strong data-start=\"894\" data-end=\"913\">Programme Title:</strong>     &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Master of Business Administration<br><strong data-start=\"953\" data-end=\"962\">Level:</strong>          &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Postgraduate<br><strong data-start=\"986\" data-end=\"998\">Duration:</strong>        &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2 Years (4 Semesters)<br><strong data-start=\"1029\" data-end=\"1046\">Mode of Study:</strong>     &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Regular / Online / Distance<br><strong data-start=\"1080\" data-end=\"1095\">Affiliation:</strong>      &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; UGC, AICTE, NAAC<br><strong data-start=\"1119\" data-end=\"1143\">Eligibility Criteria:</strong>  &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Graduation in any discipline from a recognized university<br><strong data-start=\"1204\" data-end=\"1221\">Core Subjects:</strong>     &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Management Principles, Marketing, Finance, Human Resource Management, Operations, Business Analytics<br><strong data-start=\"1328\" data-end=\"1344\">Average Fees:</strong>     &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;₹25,000 – ₹1,00,000 per semester<br><strong data-start=\"1383\" data-end=\"1410\">Assessment &amp; Evaluation:</strong>  &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Assignments + Case Studies + Semester Exams<br><strong data-start=\"1457\" data-end=\"1476\">Specialisations:</strong>    &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Marketing, Finance, HR, Operations, International Business, Digital Marketing, Business Analytics</p><hr><h6 data-section-id=\"rh3c0z\" data-start=\"1585\" data-end=\"1611\"><span role=\"text\"><strong data-start=\"1588\" data-end=\"1611\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"1613\" data-end=\"1706\">The MBA curriculum focuses on business management, leadership, and strategic decision-making.</p><h6 data-section-id=\"1ogneya\" data-start=\"1708\" data-end=\"1729\"><span role=\"text\"><strong data-start=\"1712\" data-end=\"1729\">Core Subjects</strong></span></h6><ul><li data-start=\"1730\" data-end=\"1942\">Principles of Management</li><li data-start=\"1730\" data-end=\"1942\">Marketing Management</li><li data-start=\"1730\" data-end=\"1942\">Financial Management</li><li data-start=\"1730\" data-end=\"1942\">Human Resource Management</li><li data-start=\"1730\" data-end=\"1942\">Business Communication</li><li data-start=\"1730\" data-end=\"1942\">Organizational Behavior</li><li data-start=\"1730\" data-end=\"1942\">Operations Management</li><li data-start=\"1730\" data-end=\"1942\">Business Analytics</li></ul><h6 data-section-id=\"1tnkfuw\" data-start=\"1944\" data-end=\"1986\"><span role=\"text\"><strong data-start=\"1948\" data-end=\"1986\">Elective / Specialization Subjects</strong></span></h6><ul><li data-start=\"1987\" data-end=\"2141\">Digital Marketing</li><li data-start=\"1987\" data-end=\"2141\">International Business</li><li data-start=\"1987\" data-end=\"2141\">Supply Chain Management</li><li data-start=\"1987\" data-end=\"2141\">Financial Planning</li><li data-start=\"1987\" data-end=\"2141\">Entrepreneurship Development</li><li data-start=\"1987\" data-end=\"2141\">Retail Management</li></ul><hr><h6 data-section-id=\"mm6aog\" data-start=\"2148\" data-end=\"2177\"><span role=\"text\"><strong data-start=\"2151\" data-end=\"2177\">Eligibility &amp; Duration</strong></span></h6><p data-start=\"2179\" data-end=\"2385\"><strong data-start=\"2179\" data-end=\"2195\">Eligibility:</strong> Graduation in any stream from a recognized university<br><strong data-start=\"2252\" data-end=\"2273\">Minimum Duration:</strong> 2 years (4 semesters)<br><strong data-start=\"2298\" data-end=\"2319\">Maximum Duration:</strong> 4 years (depending on university)<br><strong data-start=\"2356\" data-end=\"2370\">Age Limit:</strong> No age limit</p><hr><h6 data-section-id=\"12q771d\" data-start=\"2392\" data-end=\"2418\"><span role=\"text\"><strong data-start=\"2395\" data-end=\"2418\">Admission Procedure</strong></span></h6><ul><li data-start=\"2420\" data-end=\"2693\">Fill out the online/offline application form</li><li data-start=\"2420\" data-end=\"2693\">Submit required documents (graduation marksheets, ID proof, photo)</li><li data-start=\"2420\" data-end=\"2693\">Pay application/admission fee</li><li data-start=\"2420\" data-end=\"2693\">Some institutes may conduct entrance exams (CAT, MAT, etc.) or interviews</li><li data-start=\"2420\" data-end=\"2693\">Admission confirmation and enrollment</li></ul><hr><h6 data-section-id=\"1ex0xgy\" data-start=\"2700\" data-end=\"2726\"><span role=\"text\"><strong data-start=\"2703\" data-end=\"2726\">Top Specializations</strong></span></h6><ul><li data-start=\"2728\" data-end=\"2890\">MBA in Marketing</li><li data-start=\"2728\" data-end=\"2890\">MBA in Finance</li><li data-start=\"2728\" data-end=\"2890\">MBA in Human Resource Management</li><li data-start=\"2728\" data-end=\"2890\">MBA in Operations</li><li data-start=\"2728\" data-end=\"2890\">MBA in Business Analytics</li><li data-start=\"2728\" data-end=\"2890\">MBA in International Business</li></ul><hr><h6 data-section-id=\"1a54h3\" data-start=\"2897\" data-end=\"2926\"><span role=\"text\"><strong data-start=\"2900\" data-end=\"2926\">Career Scope After MBA</strong></span></h6><h6 data-section-id=\"p64cbj\" data-start=\"2928\" data-end=\"2954\"><span role=\"text\"><strong data-start=\"2932\" data-end=\"2954\">Top Career Options</strong></span></h6><ul><li data-start=\"2955\" data-end=\"3092\">Business Manager</li><li data-start=\"2955\" data-end=\"3092\">Marketing Manager</li><li data-start=\"2955\" data-end=\"3092\">HR Manager</li><li data-start=\"2955\" data-end=\"3092\">Financial Analyst</li><li data-start=\"2955\" data-end=\"3092\">Operations Manager</li><li data-start=\"2955\" data-end=\"3092\">Entrepreneur / Startup Founder</li></ul><h6 data-section-id=\"1qmqpba\" data-start=\"3094\" data-end=\"3124\"><span role=\"text\"><strong data-start=\"3098\" data-end=\"3124\">Higher Studies Options</strong></span></h6><ul><li data-start=\"3125\" data-end=\"3198\">Ph.D. in Management</li><li data-start=\"3125\" data-end=\"3198\">Professional Certifications</li><li data-start=\"3125\" data-end=\"3198\">Executive MBA</li></ul><hr><h6 data-section-id=\"9dt57q\" data-start=\"3205\" data-end=\"3222\"><span role=\"text\"><strong data-start=\"3208\" data-end=\"3222\">Conclusion</strong></span></h6><p data-start=\"3224\" data-end=\"3507\">MBA is one of the most popular and valuable postgraduate programs for building a successful career in management and business. With practical learning, multiple specializations, and strong career opportunities, it provides a solid foundation for corporate roles and entrepreneurship.</p>', 'MBA is a highly valued postgraduate program focused on business management, leadership, and strategic decision-making. It prepares students for managerial roles in various industries like finance, marketing, human resources, and operations.', 'MBA', 'MBA is a highly valued postgraduate program focused on business management, leadership, and strategic decision-making. It prepares students for managerial roles in various industries like finance, marketing, human resources, and operations.', 'mba', NULL, '1', '2026-04-17 12:20:35', '2026-04-17 12:20:35');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('11', '5', '1', 'B.Lib', 'Bachelor of Library Science', 'new-assets/img/courses/blib_banner.png', 'b-lib', '1 Year (2 Semesters)', 'Graduation in any stream from a recognized university', '₹8,000 – ₹25,000 per year', '<p data-start=\"429\" data-end=\"855\">The Bachelor of Library Science (B.Lib) program is designed for students who want to build a career in library and information science. It focuses on the organization, management, and dissemination of information in both physical and digital formats. The course develops skills in cataloguing, classification, information retrieval, and digital library systems, making students capable of handling modern library technologies.</p><hr><h6 data-section-id=\"1j5qwet\" data-start=\"862\" data-end=\"881\"><span role=\"text\"><strong data-start=\"865\" data-end=\"881\">Key Features</strong></span></h6><p data-start=\"883\" data-end=\"1529\"><strong data-start=\"883\" data-end=\"902\">Programme Title</strong>    Bachelor of Library Science<br><strong data-start=\"936\" data-end=\"945\">Level</strong>         Undergraduate / Professional<br><strong data-start=\"985\" data-end=\"997\">Duration</strong>       1 Year (2 Semesters)<br><strong data-start=\"1027\" data-end=\"1044\">Mode of Study</strong>    Regular / Online / Distance<br><strong data-start=\"1078\" data-end=\"1093\">Affiliation</strong>     UGC, NAAC (as per university)<br><strong data-start=\"1130\" data-end=\"1154\">Eligibility Criteria</strong> Graduation in any stream from a recognized university<br><strong data-start=\"1211\" data-end=\"1228\">Core Subjects</strong>    Library Classification, Cataloguing, Information Sources, Library Management, Digital Libraries<br><strong data-start=\"1330\" data-end=\"1346\">Average Fees</strong>    ₹8,000 – ₹25,000 per year<br><strong data-start=\"1378\" data-end=\"1405\">Assessment &amp; Evaluation</strong> Assignments + Practical + Exams<br><strong data-start=\"1440\" data-end=\"1459\">Specialisations</strong>   Digital Library Science, Information Management, Archival Studies</p><hr><h6 data-section-id=\"rh3c0z\" data-start=\"1536\" data-end=\"1562\"><span role=\"text\"><strong data-start=\"1539\" data-end=\"1562\">Subjects &amp; Syllabus</strong></span></h6><p data-start=\"1564\" data-end=\"1666\">The B.Lib curriculum focuses on library management, information systems, and documentation techniques.</p><h6 data-section-id=\"1ogneya\" data-start=\"1668\" data-end=\"1689\"><span role=\"text\"><strong data-start=\"1672\" data-end=\"1689\">Core Subjects</strong></span></h6><ul><li data-start=\"1690\" data-end=\"1876\">Library Classification</li><li data-start=\"1690\" data-end=\"1876\">Cataloguing Theory &amp; Practice</li><li data-start=\"1690\" data-end=\"1876\">Library Management</li><li data-start=\"1690\" data-end=\"1876\">Information Sources &amp; Services</li><li data-start=\"1690\" data-end=\"1876\">Digital Library Systems</li><li data-start=\"1690\" data-end=\"1876\">Documentation &amp; Information Science</li></ul><h6 data-section-id=\"3dcoeg\" data-start=\"1878\" data-end=\"1903\"><span role=\"text\"><strong data-start=\"1882\" data-end=\"1903\">Elective Subjects</strong></span></h6><ul><li data-start=\"1904\" data-end=\"2024\">Information Technology in Libraries</li><li data-start=\"1904\" data-end=\"2024\">Archival Management</li><li data-start=\"1904\" data-end=\"2024\">Knowledge Management</li><li data-start=\"1904\" data-end=\"2024\">Digital Information Systems</li></ul><hr><h6 data-section-id=\"mm6aog\" data-start=\"2031\" data-end=\"2060\"><span role=\"text\"><strong data-start=\"2034\" data-end=\"2060\">Eligibility &amp; Duration</strong></span></h6><p data-start=\"2062\" data-end=\"2253\"><strong data-start=\"2062\" data-end=\"2078\">Eligibility:</strong> Graduation in any stream from a recognized university<br><strong data-start=\"2135\" data-end=\"2156\">Minimum Duration:</strong> 1 year<br><strong data-start=\"2166\" data-end=\"2187\">Maximum Duration:</strong> 2 years (depending on university)<br><strong data-start=\"2224\" data-end=\"2238\">Age Limit:</strong> No age limit</p><hr><h6 data-section-id=\"12q771d\" data-start=\"2260\" data-end=\"2286\"><span role=\"text\"><strong data-start=\"2263\" data-end=\"2286\">Admission Procedure</strong></span></h6><ul><li data-start=\"2288\" data-end=\"2547\">Fill out the application form (online/offline)</li><li data-start=\"2288\" data-end=\"2547\">Submit required documents (graduation marksheets, ID proof, photo)</li><li data-start=\"2288\" data-end=\"2547\">Pay application fee</li><li data-start=\"2288\" data-end=\"2547\">Admission is usually merit-based (some institutes may conduct entrance tests)</li><li data-start=\"2288\" data-end=\"2547\">Confirmation and enrollment</li></ul><hr><h6 data-section-id=\"162s00y\" data-start=\"2554\" data-end=\"2585\"><span role=\"text\"><strong data-start=\"2557\" data-end=\"2585\">Career Scope After B.Lib</strong></span></h6><h6 data-section-id=\"p64cbj\" data-start=\"2587\" data-end=\"2613\"><span role=\"text\"><strong data-start=\"2591\" data-end=\"2613\">Top Career Options</strong></span></h6><ul><li data-start=\"2614\" data-end=\"2741\">Librarian</li><li data-start=\"2614\" data-end=\"2741\">Library Assistant</li><li data-start=\"2614\" data-end=\"2741\">Information Officer</li><li data-start=\"2614\" data-end=\"2741\">Archivist</li><li data-start=\"2614\" data-end=\"2741\">Documentation Officer</li><li data-start=\"2614\" data-end=\"2741\">Digital Library Manager</li></ul><h6 data-section-id=\"1qmqpba\" data-start=\"2743\" data-end=\"2773\"><span role=\"text\"><strong data-start=\"2747\" data-end=\"2773\">Higher Studies Options</strong></span></h6><ul><li data-start=\"2774\" data-end=\"2889\">M.Lib (Master of Library Science)</li><li data-start=\"2774\" data-end=\"2889\">Ph.D. in Library Science</li><li data-start=\"2774\" data-end=\"2889\">Certification Courses in Information Science</li></ul><hr><h6 data-section-id=\"9dt57q\" data-start=\"2896\" data-end=\"2913\"><span role=\"text\"><strong data-start=\"2899\" data-end=\"2913\">Conclusion</strong></span></h6><p data-start=\"2915\" data-end=\"3195\">B.Lib is an excellent course for students interested in library science and information management. With the growing importance of digital information systems, this course offers good career opportunities in educational institutions, corporate sectors, and research organizations.</p>', 'B.Lib is a professional undergraduate degree focused on library management, information organization, and digital resources. It prepares students for careers in libraries, information centers, and documentation services.', 'b-lib', 'B.Lib is a professional undergraduate degree focused on library management, information organization, and digital resources. It prepares students for careers in libraries, information centers, and documentation services.', 'b-lib', NULL, '1', '2026-04-17 12:30:57', '2026-04-17 12:30:57');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('12', '5', '1', 'NURSING', 'NURSING (B.Sc / GNM)', 'new-assets/img/courses/nursing_banner.png', 'nursing', 'B.Sc Nursing: 4 Years / GNM: 3 Years', '12th Science (PCB) minimum 45–50%', '₹15,000 – ₹70,000 per year', '<p>In the Nursing course, students are trained in human anatomy, physiology, patient care techniques, first aid, medical ethics, and hospital management. The main focus of this program is to develop strong skills in patient care and support the healthcare system effectively.</p><hr><h6 data-section-id=\"1cups0j\" data-start=\"283\" data-end=\"317\">Key Features</h6><div class=\"TyagGW_tableContainer\"><div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\"><figure class=\"table\"><table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"319\" data-end=\"818\"><thead data-start=\"319\" data-end=\"348\"><tr data-start=\"319\" data-end=\"348\"><th class=\"\" data-start=\"319\" data-end=\"333\" data-col-size=\"sm\"><strong data-start=\"321\" data-end=\"332\">Heading</strong></th><th class=\"\" data-start=\"333\" data-end=\"348\" data-col-size=\"md\"><strong data-start=\"335\" data-end=\"346\">Details</strong></th></tr></thead><tbody data-start=\"378\" data-end=\"818\"><tr data-start=\"378\" data-end=\"424\"><td data-start=\"378\" data-end=\"392\" data-col-size=\"sm\">Course Name</td><td data-start=\"392\" data-end=\"424\" data-col-size=\"md\">Nursing (B.Sc Nursing / GNM)</td></tr><tr data-start=\"425\" data-end=\"476\"><td data-start=\"425\" data-end=\"436\" data-col-size=\"sm\">Duration</td><td data-col-size=\"md\" data-start=\"436\" data-end=\"476\">B.Sc Nursing: 4 Years / GNM: 3 Years</td></tr><tr data-start=\"477\" data-end=\"528\"><td data-start=\"477\" data-end=\"491\" data-col-size=\"sm\">Eligibility</td><td data-col-size=\"md\" data-start=\"491\" data-end=\"528\">12th Science (PCB) minimum 45–50%</td></tr><tr data-start=\"529\" data-end=\"574\"><td data-start=\"529\" data-end=\"549\" data-col-size=\"sm\">Admission Process</td><td data-col-size=\"md\" data-start=\"549\" data-end=\"574\">Merit / Entrance Exam</td></tr><tr data-start=\"575\" data-end=\"633\"><td data-start=\"575\" data-end=\"592\" data-col-size=\"sm\">Training Areas</td><td data-col-size=\"md\" data-start=\"592\" data-end=\"633\">Hospital, ICU, Ward, Community Health</td></tr><tr data-start=\"634\" data-end=\"678\"><td data-start=\"634\" data-end=\"647\" data-col-size=\"sm\">Internship</td><td data-col-size=\"md\" data-start=\"647\" data-end=\"678\">Mandatory Clinical Training</td></tr><tr data-start=\"679\" data-end=\"751\"><td data-start=\"679\" data-end=\"691\" data-col-size=\"sm\">Job Roles</td><td data-col-size=\"md\" data-start=\"691\" data-end=\"751\">Staff Nurse, ICU Nurse, OT Nurse, Community Health Nurse</td></tr><tr data-start=\"752\" data-end=\"818\"><td data-start=\"752\" data-end=\"767\" data-col-size=\"sm\">Salary Scope</td><td data-start=\"767\" data-end=\"818\" data-col-size=\"md\">₹2.5 LPA – ₹8 LPA (with experience increase)</td></tr></tbody></table></figure></div></div><hr><h6 data-section-id=\"wuob72\" data-start=\"825\" data-end=\"851\"><strong>Subjects / Syllabus</strong></h6><ul><li data-start=\"852\" data-end=\"1074\">Anatomy &amp; Physiology</li><li data-start=\"852\" data-end=\"1074\">Microbiology</li><li data-start=\"852\" data-end=\"1074\">Nutrition &amp; Dietetics</li><li data-start=\"852\" data-end=\"1074\">Pharmacology</li><li data-start=\"852\" data-end=\"1074\">Medical-Surgical Nursing</li><li data-start=\"852\" data-end=\"1074\">Pediatric Nursing</li><li data-start=\"852\" data-end=\"1074\">Psychiatric Nursing</li><li data-start=\"852\" data-end=\"1074\">Community Health Nursing</li><li data-start=\"852\" data-end=\"1074\">Midwifery &amp; Obstetric Nursing</li></ul><hr><h6 data-section-id=\"1088sav\" data-start=\"1081\" data-end=\"1108\"><strong>Career Opportunities</strong></h6><ul><li data-start=\"1109\" data-end=\"1276\">Government Hospitals</li><li data-start=\"1109\" data-end=\"1276\">Private Hospitals</li><li data-start=\"1109\" data-end=\"1276\">Army Nursing Services</li><li data-start=\"1109\" data-end=\"1276\">Nursing Homes &amp; Clinics</li><li data-start=\"1109\" data-end=\"1276\">Abroad (High Demand Countries)</li><li data-start=\"1109\" data-end=\"1276\">ICUs / Emergency Care Units</li></ul><h6 data-section-id=\"tpibef\" data-start=\"1308\" data-end=\"1335\">Skills You Will Learn</h6><ul><li data-start=\"1336\" data-end=\"1483\">Patient monitoring</li><li data-start=\"1336\" data-end=\"1483\">Injection &amp; medication handling</li><li data-start=\"1336\" data-end=\"1483\">Wound dressing</li><li data-start=\"1336\" data-end=\"1483\">Emergency care response</li><li data-start=\"1336\" data-end=\"1483\">Communication with doctors &amp; patients</li></ul>', 'Nursing is a healthcare profession in which patients are cared for, treatment support is provided, and health education is delivered. This course trains students for work in hospital and clinical environments.', 'nursing', 'Nursing is a healthcare profession in which patients are cared for, treatment support is provided, and health education is delivered. This course trains students for work in hospital and clinical environments.', 'nursing', NULL, '1', '2026-04-17 12:41:56', '2026-04-17 12:43:34');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('13', '5', '1', 'Pharmacy', 'Pharmacy', 'new-assets/img/courses/pharmacy_banner.png', 'pharmacy', 'D.Pharm: 2 Years / B.Pharm: 4 Years', '12th Science (PCB) minimum 45–50%', '₹10,000 – ₹45,000 per year', '<p data-start=\"516\" data-end=\"817\">Pharmacy is a vital branch of healthcare that deals with the study of drugs and medicines. Students learn how medicines are developed, tested, manufactured, and safely distributed to patients. The course also provides knowledge about human diseases and how different drugs work to cure or manage them.</p><p data-start=\"819\" data-end=\"1073\">Pharmacy professionals play an important role between doctors and patients by ensuring the correct and safe use of medicines. After completing this course, students can work in hospitals, pharmaceutical companies, research labs, and community pharmacies.</p><hr><h6 data-section-id=\"etycth\" data-start=\"1080\" data-end=\"1097\">Key Features</h6><figure class=\"table\"><table><thead><tr><th>Heading</th><th>Details</th></tr></thead><tbody><tr><td>Course Name</td><td>Pharmacy (D.Pharm / B.Pharm)</td></tr><tr><td>Duration</td><td>D.Pharm: 2 Years / B.Pharm: 4 Years</td></tr><tr><td>Eligibility</td><td>12th Science (PCB/PCM) minimum 45–50%</td></tr><tr><td>Admission Process</td><td>Merit / Entrance Exam (college-wise)</td></tr><tr><td>Training Areas</td><td>Hospital Pharmacy, Industrial Pharmacy, Drug Labs</td></tr><tr><td>Practical Training</td><td>Laboratory experiments &amp; clinical exposure</td></tr><tr><td>Internship</td><td>Industry or hospital-based training included</td></tr><tr><td>Job Roles</td><td>Pharmacist, Medical Representative, Drug Inspector, QA/QC Officer</td></tr><tr><td>Salary Scope</td><td>₹2.5 LPA – ₹10 LPA (experience &amp; specialization based)</td></tr><tr><td>Industry Demand</td><td>High demand in healthcare &amp; pharmaceutical sector</td></tr></tbody></table></figure><hr><h6 data-section-id=\"svb8o4\" data-start=\"1350\" data-end=\"1375\">Subjects &amp; Syllabus</h6><ul><li data-start=\"1376\" data-end=\"1675\">Pharmaceutical Chemistry</li><li data-start=\"1376\" data-end=\"1675\">Pharmacology</li><li data-start=\"1376\" data-end=\"1675\">Pharmaceutics</li><li data-start=\"1376\" data-end=\"1675\">Pharmacognosy</li><li data-start=\"1376\" data-end=\"1675\">Human Anatomy &amp; Physiology</li><li data-start=\"1376\" data-end=\"1675\">Biochemistry</li><li data-start=\"1376\" data-end=\"1675\">Microbiology</li><li data-start=\"1376\" data-end=\"1675\">Hospital &amp; Clinical Pharmacy</li><li data-start=\"1376\" data-end=\"1675\">Drug Regulatory Affairs</li><li data-start=\"1376\" data-end=\"1675\">Pharmaceutical Analysis</li><li data-start=\"1376\" data-end=\"1675\">Biopharmaceutics &amp; Pharmacokinetics</li><li data-start=\"1376\" data-end=\"1675\">Medicinal Chemistry</li></ul><hr><h6 data-section-id=\"1bm2uwp\" data-start=\"1682\" data-end=\"1708\">Career Opportunities</h6><ul><li data-start=\"1709\" data-end=\"1964\">Pharmacist (Hospital &amp; Retail)</li><li data-start=\"1709\" data-end=\"1964\">Medical Representative</li><li data-start=\"1709\" data-end=\"1964\">Drug Inspector</li><li data-start=\"1709\" data-end=\"1964\">Pharmaceutical Research Scientist</li><li data-start=\"1709\" data-end=\"1964\">Quality Control/Quality Assurance Officer</li><li data-start=\"1709\" data-end=\"1964\">Production Chemist</li><li data-start=\"1709\" data-end=\"1964\">Clinical Pharmacist</li><li data-start=\"1709\" data-end=\"1964\">Lecturer/Teacher (after higher studies)</li></ul><hr><h6 data-section-id=\"1ra7cog\" data-start=\"1971\" data-end=\"1998\">Skills You Will Learn</h6><ul><li data-start=\"1999\" data-end=\"2247\">Drug knowledge and prescription understanding</li><li data-start=\"1999\" data-end=\"2247\">Laboratory and research skills</li><li data-start=\"1999\" data-end=\"2247\">Patient counseling and communication</li><li data-start=\"1999\" data-end=\"2247\">Accuracy in medicine dispensing</li><li data-start=\"1999\" data-end=\"2247\">Analytical and problem-solving skills</li><li data-start=\"1999\" data-end=\"2247\">Understanding of medical laws and ethics</li></ul><hr><h6 data-section-id=\"p320wl\" data-start=\"2254\" data-end=\"2270\">Conclusion</h6><p data-start=\"2271\" data-end=\"2520\">Pharmacy is a highly respected and stable career field in healthcare. It offers strong job opportunities in hospitals, pharmaceutical companies, and research sectors. With the growing healthcare industry, pharmacy professionals are always in demand.</p>', 'Pharmacy is a healthcare and science-based field that focuses on the preparation, dispensing, and safe use of medicines. It trains students to understand drugs, their effects on the human body, and their role in treating diseases.', 'pharmacy', 'Pharmacy is a healthcare and science-based field that focuses on the preparation, dispensing, and safe use of medicines. It trains students to understand drugs, their effects on the human body, and their role in treating diseases.', 'pharmacy', NULL, '1', '2026-04-17 12:55:52', '2026-04-17 12:55:52');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('14', '5', '1', 'Engineering', 'Engineering (B.Tech / Diploma / M.Tech)', 'new-assets/img/courses/engineering_banner.png', 'Engineering', 'B.Tech: 4 Years / Diploma: 3 Years / M.Tech: 2 Years', '12th Science (PCM) minimum 45–50%', '₹35,000 – ₹90,000 per year', '<p data-start=\"602\" data-end=\"871\">Engineering is one of the most popular and respected career fields that combines science, mathematics, and technology to solve real-world problems. Students learn how to design, build, and maintain systems such as buildings, machines, software, and electrical networks.</p><p data-start=\"873\" data-end=\"1157\">During the course, students gain both theoretical knowledge and practical skills through labs, projects, and industrial training. Engineering graduates have opportunities in government sectors, private companies, IT industries, construction, manufacturing, and research organizations.</p><hr><h6 data-section-id=\"etycth\" data-start=\"1164\" data-end=\"1181\">Key Features</h6><figure class=\"table\"><table><thead><tr><th>Heading</th><th>Details</th></tr></thead><tbody><tr><td>Course Name</td><td>Engineering (B.Tech / Diploma / M.Tech)</td></tr><tr><td>Duration</td><td>B.Tech: 4 Years / Diploma: 3 Years / M.Tech: 2 Years</td></tr><tr><td>Eligibility</td><td>12th Science (PCM) minimum 45–50%</td></tr><tr><td>Admission Process</td><td>Merit / Entrance Exam (JEE / State Exams / College Wise)</td></tr><tr><td>Training Areas</td><td>Labs, Workshops, Industrial Training, Projects</td></tr><tr><td>Internship</td><td>Mandatory Industrial Internship</td></tr><tr><td>Job Roles</td><td>Software Engineer, Civil Engineer, Mechanical Engineer, Electrical Engineer</td></tr><tr><td>Salary Scope</td><td>₹3 LPA – ₹15 LPA (depends on skills &amp; experience)</td></tr></tbody></table></figure><hr><h6 data-section-id=\"svb8o4\" data-start=\"1432\" data-end=\"1457\">Subjects &amp; Syllabus</h6><ul><li data-start=\"1458\" data-end=\"1816\">Engineering Mathematics</li><li data-start=\"1458\" data-end=\"1816\">Physics &amp; Chemistry (basic level)</li><li data-start=\"1458\" data-end=\"1816\">Computer Programming</li><li data-start=\"1458\" data-end=\"1816\">Engineering Mechanics</li><li data-start=\"1458\" data-end=\"1816\">Electrical &amp; Electronics Engineering</li><li data-start=\"1458\" data-end=\"1816\">Thermodynamics</li><li data-start=\"1458\" data-end=\"1816\">Data Structures &amp; Algorithms (CSE)</li><li data-start=\"1458\" data-end=\"1816\">Fluid Mechanics</li><li data-start=\"1458\" data-end=\"1816\">Structural Analysis (Civil)</li><li data-start=\"1458\" data-end=\"1816\">Machine Design (Mechanical)</li><li data-start=\"1458\" data-end=\"1816\">Control Systems</li><li data-start=\"1458\" data-end=\"1816\">Project Work &amp; Industrial Training</li></ul><hr><h6 data-section-id=\"1bm2uwp\" data-start=\"1823\" data-end=\"1849\">Career Opportunities</h6><ul><li data-start=\"1850\" data-end=\"2090\">Software Engineer</li><li data-start=\"1850\" data-end=\"2090\">Civil Engineer</li><li data-start=\"1850\" data-end=\"2090\">Mechanical Engineer</li><li data-start=\"1850\" data-end=\"2090\">Electrical Engineer</li><li data-start=\"1850\" data-end=\"2090\">Data Scientist</li><li data-start=\"1850\" data-end=\"2090\">Network Engineer</li><li data-start=\"1850\" data-end=\"2090\">Site Engineer</li><li data-start=\"1850\" data-end=\"2090\">Project Manager</li><li data-start=\"1850\" data-end=\"2090\">Research &amp; Development Engineer</li><li data-start=\"1850\" data-end=\"2090\">Government Engineer (PSU/SSC/IES)</li></ul><hr><h6 data-section-id=\"1ra7cog\" data-start=\"2097\" data-end=\"2124\">Skills You Will Learn</h6><ul><li data-start=\"2125\" data-end=\"2350\">Problem-solving and analytical thinking</li><li data-start=\"2125\" data-end=\"2350\">Technical and design skills</li><li data-start=\"2125\" data-end=\"2350\">Programming and software development (CSE)</li><li data-start=\"2125\" data-end=\"2350\">Machine and system design</li><li data-start=\"2125\" data-end=\"2350\">Teamwork and project management</li><li data-start=\"2125\" data-end=\"2350\">Critical thinking and innovation</li></ul><hr><h6 data-section-id=\"p320wl\" data-start=\"2357\" data-end=\"2373\">Conclusion</h6><p data-start=\"2374\" data-end=\"2613\">Engineering is a dynamic and future-oriented career that offers vast opportunities in almost every industry. It helps students develop technical expertise and innovation skills, making them valuable in both national and global job markets.</p>', 'Engineering is a professional field that applies scientific and mathematical principles to design, develop, and improve machines, structures, systems, and technology. It offers a wide range of specializations like Civil, Mechanical, Electrical, Computer Science, and Electronics Engineering.', 'engineering', 'Engineering is a professional field that applies scientific and mathematical principles to design, develop, and improve machines, structures, systems, and technology. It offers a wide range of specializations like Civil, Mechanical, Electrical, Computer Science, and Electronics Engineering.', 'engineering', NULL, '1', '2026-04-17 13:05:11', '2026-04-17 13:05:11');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('16', '5', '4', 'Vocational', 'Vocational', 'new-assets/img/courses/vocational_banner.png', 'vocational', '6 Months to 3 Years (varies by course)', '10th / 12th Pass (depends on course)', '₹6,000 – ₹35,000 per year', '<p data-start=\"509\" data-end=\"743\">Vocational education is designed to develop practical and technical skills rather than only theoretical knowledge. It focuses on real-world job training so that students can directly enter the workforce after completing their studies.</p><p data-start=\"745\" data-end=\"1013\">These courses are highly industry-focused and include training in fields like healthcare, engineering trades, computer applications, hospitality, fashion design, and many more. Vocational education is ideal for students who want quick employment and skill development.</p><hr><h6 data-section-id=\"etycth\" data-start=\"1020\" data-end=\"1037\">Key Features</h6><div class=\"TyagGW_tableContainer\"><div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\"><figure class=\"table\"><table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1039\" data-end=\"1635\"><thead data-start=\"1039\" data-end=\"1072\"><tr data-start=\"1039\" data-end=\"1072\"><th class=\"\" data-start=\"1039\" data-end=\"1061\" data-col-size=\"sm\">Heading</th><th class=\"\" data-start=\"1061\" data-end=\"1072\" data-col-size=\"md\">Details</th></tr></thead><tbody data-start=\"1107\" data-end=\"1635\"><tr data-start=\"1107\" data-end=\"1167\"><td data-start=\"1107\" data-end=\"1128\" data-col-size=\"sm\">Course Type</td><td data-start=\"1128\" data-end=\"1167\" data-col-size=\"md\">Skill-based / Job-oriented training</td></tr><tr data-start=\"1168\" data-end=\"1234\"><td data-start=\"1168\" data-end=\"1189\" data-col-size=\"sm\">Focus Area</td><td data-col-size=\"md\" data-start=\"1189\" data-end=\"1234\">Practical knowledge and hands-on training</td></tr><tr data-start=\"1235\" data-end=\"1298\"><td data-start=\"1235\" data-end=\"1256\" data-col-size=\"sm\">Duration</td><td data-start=\"1256\" data-end=\"1298\" data-col-size=\"md\">6 Months to 3 Years (varies by course)</td></tr><tr data-start=\"1299\" data-end=\"1360\"><td data-start=\"1299\" data-end=\"1320\" data-col-size=\"sm\">Eligibility</td><td data-col-size=\"md\" data-start=\"1320\" data-end=\"1360\">10th / 12th Pass (depends on course)</td></tr><tr data-start=\"1361\" data-end=\"1427\"><td data-start=\"1361\" data-end=\"1382\" data-col-size=\"sm\">Training Method</td><td data-col-size=\"md\" data-start=\"1382\" data-end=\"1427\">Classroom + Practical + Industry exposure</td></tr><tr data-start=\"1428\" data-end=\"1487\"><td data-start=\"1428\" data-end=\"1449\" data-col-size=\"sm\">Job Readiness</td><td data-col-size=\"md\" data-start=\"1449\" data-end=\"1487\">Direct employment-focused learning</td></tr><tr data-start=\"1488\" data-end=\"1556\"><td data-start=\"1488\" data-end=\"1509\" data-col-size=\"sm\">Certification</td><td data-start=\"1509\" data-end=\"1556\" data-col-size=\"md\">Government / Private recognized certificate</td></tr><tr data-start=\"1557\" data-end=\"1635\"><td data-start=\"1557\" data-end=\"1578\" data-col-size=\"sm\">Industry Scope</td><td data-col-size=\"md\" data-start=\"1578\" data-end=\"1635\">Healthcare, IT, Retail, Hospitality, Technical fields</td></tr></tbody></table></figure></div></div><hr><h6 data-section-id=\"16666km\" data-start=\"1642\" data-end=\"1673\">Subjects / Training Areas</h6><ul><li data-start=\"1674\" data-end=\"1999\">Basic Computer Skills</li><li data-start=\"1674\" data-end=\"1999\">Communication Skills</li><li data-start=\"1674\" data-end=\"1999\">Technical Trade Training (Electrician, Fitter, Mechanic, etc.)</li><li data-start=\"1674\" data-end=\"1999\">Healthcare &amp; Nursing Basics</li><li data-start=\"1674\" data-end=\"1999\">Hospitality Management</li><li data-start=\"1674\" data-end=\"1999\">Beauty &amp; Wellness Training</li><li data-start=\"1674\" data-end=\"1999\">Retail Management</li><li data-start=\"1674\" data-end=\"1999\">Fashion Designing Basics</li><li data-start=\"1674\" data-end=\"1999\">Industrial Safety &amp; Tools Handling</li><li data-start=\"1674\" data-end=\"1999\">Customer Service Skills</li></ul><hr><h6 data-section-id=\"1bm2uwp\" data-start=\"2006\" data-end=\"2032\">Career Opportunities</h6><ul><li data-start=\"2033\" data-end=\"2308\">Technician (Electrical / Mechanical)</li><li data-start=\"2033\" data-end=\"2308\">Data Entry Operator</li><li data-start=\"2033\" data-end=\"2308\">Healthcare Assistant</li><li data-start=\"2033\" data-end=\"2308\">Retail Sales Executive</li><li data-start=\"2033\" data-end=\"2308\">Hospitality Staff (Hotel/Restaurant)</li><li data-start=\"2033\" data-end=\"2308\">Beautician / Makeup Artist</li><li data-start=\"2033\" data-end=\"2308\">Computer Operator</li><li data-start=\"2033\" data-end=\"2308\">Skilled Trade Worker</li><li data-start=\"2033\" data-end=\"2308\">Entrepreneur / Self-employed Worker</li></ul><hr><h6 data-section-id=\"1ra7cog\" data-start=\"2315\" data-end=\"2342\">Skills You Will Learn</h6><ul><li data-start=\"2343\" data-end=\"2531\">Practical job skills</li><li data-start=\"2343\" data-end=\"2531\">Technical expertise</li><li data-start=\"2343\" data-end=\"2531\">Communication and customer handling</li><li data-start=\"2343\" data-end=\"2531\">Problem-solving ability</li><li data-start=\"2343\" data-end=\"2531\">Industry-specific tools usage</li><li data-start=\"2343\" data-end=\"2531\">Workplace discipline and teamwork</li></ul><hr><h6 data-section-id=\"p320wl\" data-start=\"2538\" data-end=\"2554\">Conclusion</h6><p data-start=\"2555\" data-end=\"2761\">Vocational courses are an excellent choice for students who want early employment and practical skills. These programs focus on real-world training, making students job-ready and confident in their careers.</p>', 'Vocational courses are job-oriented programs that provide practical skills and hands-on training. These courses help students become industry-ready and start working early in their careers.', 'vocatinal', 'Vocational courses are job-oriented programs that provide practical skills and hands-on training. These courses help students become industry-ready and start working early in their careers.', 'vocatinal', NULL, '1', '2026-04-17 13:16:13', '2026-04-17 13:16:13');
INSERT INTO `courses` (`id`, `category_id`, `department_id`, `name`, `full_name`, `image`, `alt`, `duration`, `eligibilty`, `fees`, `content`, `short_content`, `meta_title`, `meta_description`, `slug`, `ld_schema`, `status`, `created_at`, `updated_at`) VALUES ('17', '5', '2', 'Ph.D', 'Doctor of Philosophy', 'new-assets/img/courses/phd_banner.png', 'Doctor of Philosophy', '3 to 6 Years (varies by research topic)', 'Master’s Degree (Postgraduate) with minimum required marks', '₹15,000 – ₹90,000 per year', '<p data-start=\"500\" data-end=\"742\">PhD (Doctor of Philosophy) is an advanced academic program that focuses on deep research in a specific subject area. Students choose a research topic and work under the guidance of a supervisor to develop new findings, theories, or solutions.</p><p data-start=\"744\" data-end=\"1058\">During the course, scholars conduct literature reviews, collect data, perform analysis, and submit a thesis or dissertation. The PhD program develops critical thinking, analytical ability, and research skills. It opens opportunities in universities, research institutions, government organizations, and industries.</p><hr><h6 data-section-id=\"etycth\" data-start=\"1065\" data-end=\"1082\">Key Features</h6><div class=\"TyagGW_tableContainer\"><div class=\"group TyagGW_tableWrapper flex flex-col-reverse w-fit\" tabindex=\"-1\"><figure class=\"table\"><table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1084\" data-end=\"1636\"><thead data-start=\"1084\" data-end=\"1115\"><tr data-start=\"1084\" data-end=\"1115\"><th class=\"\" data-start=\"1084\" data-end=\"1104\" data-col-size=\"sm\">Heading</th><th class=\"\" data-start=\"1104\" data-end=\"1115\" data-col-size=\"md\">Details</th></tr></thead><tbody data-start=\"1148\" data-end=\"1636\"><tr data-start=\"1148\" data-end=\"1197\"><td data-start=\"1148\" data-end=\"1167\" data-col-size=\"sm\">Course Name</td><td data-start=\"1167\" data-end=\"1197\" data-col-size=\"md\">PhD (Doctor of Philosophy)</td></tr><tr data-start=\"1198\" data-end=\"1252\"><td data-start=\"1198\" data-end=\"1217\" data-col-size=\"sm\">Course Type</td><td data-start=\"1217\" data-end=\"1252\" data-col-size=\"md\">Research-based Doctoral Program</td></tr><tr data-start=\"1253\" data-end=\"1315\"><td data-start=\"1253\" data-end=\"1272\" data-col-size=\"sm\">Duration</td><td data-start=\"1272\" data-end=\"1315\" data-col-size=\"md\">3 to 6 Years (varies by research topic)</td></tr><tr data-start=\"1316\" data-end=\"1397\"><td data-start=\"1316\" data-end=\"1335\" data-col-size=\"sm\">Eligibility</td><td data-start=\"1335\" data-end=\"1397\" data-col-size=\"md\">Master’s Degree (Postgraduate) with minimum required marks</td></tr><tr data-start=\"1398\" data-end=\"1464\"><td data-start=\"1398\" data-end=\"1417\" data-col-size=\"sm\">Admission Process</td><td data-start=\"1417\" data-end=\"1464\" data-col-size=\"md\">Entrance Exam + Interview (University Wise)</td></tr><tr data-start=\"1465\" data-end=\"1518\"><td data-start=\"1465\" data-end=\"1484\" data-col-size=\"sm\">Focus Area</td><td data-start=\"1484\" data-end=\"1518\" data-col-size=\"md\">Advanced Research &amp; Innovation</td></tr><tr data-start=\"1519\" data-end=\"1581\"><td data-start=\"1519\" data-end=\"1539\" data-col-size=\"sm\">Training Method</td><td data-start=\"1539\" data-end=\"1581\" data-col-size=\"md\">Research work under expert supervision</td></tr><tr data-start=\"1582\" data-end=\"1636\"><td data-start=\"1582\" data-end=\"1602\" data-col-size=\"sm\">Final Requirement</td><td data-start=\"1602\" data-end=\"1636\" data-col-size=\"md\">Thesis/Dissertation Submission</td></tr></tbody></table></figure></div></div><hr><h6 data-section-id=\"1blp3kv\" data-start=\"1643\" data-end=\"1674\">Research Areas / Subjects</h6><ul><li data-start=\"1675\" data-end=\"1910\">Science &amp; Technology</li><li data-start=\"1675\" data-end=\"1910\">Engineering &amp; Applied Sciences</li><li data-start=\"1675\" data-end=\"1910\">Management Studies</li><li data-start=\"1675\" data-end=\"1910\">Social Sciences</li><li data-start=\"1675\" data-end=\"1910\">Humanities &amp; Arts</li><li data-start=\"1675\" data-end=\"1910\">Medical &amp; Health Sciences</li><li data-start=\"1675\" data-end=\"1910\">Computer Science &amp; AI</li><li data-start=\"1675\" data-end=\"1910\">Law and Political Science</li><li data-start=\"1675\" data-end=\"1910\">Economics &amp; Commerce</li></ul><hr><h6 data-section-id=\"1bm2uwp\" data-start=\"1917\" data-end=\"1943\">Career Opportunities</h6><ul><li data-start=\"1944\" data-end=\"2162\">University Professor / Lecturer</li><li data-start=\"1944\" data-end=\"2162\">Research Scientist</li><li data-start=\"1944\" data-end=\"2162\">Data Analyst / Research Analyst</li><li data-start=\"1944\" data-end=\"2162\">Policy Advisor</li><li data-start=\"1944\" data-end=\"2162\">Government Research Officer</li><li data-start=\"1944\" data-end=\"2162\">Corporate Research &amp; Development Expert</li><li data-start=\"1944\" data-end=\"2162\">Author / Academic Writer</li></ul><hr><h6 data-section-id=\"1ra7cog\" data-start=\"2169\" data-end=\"2196\">Skills You Will Learn</h6><ul><li data-start=\"2197\" data-end=\"2411\">Advanced research methodology</li><li data-start=\"2197\" data-end=\"2411\">Critical thinking and analysis</li><li data-start=\"2197\" data-end=\"2411\">Data collection and interpretation</li><li data-start=\"2197\" data-end=\"2411\">Academic writing and publishing</li><li data-start=\"2197\" data-end=\"2411\">Problem-solving and innovation</li><li data-start=\"2197\" data-end=\"2411\">Independent research capability</li></ul><hr><h6 data-section-id=\"p320wl\" data-start=\"2418\" data-end=\"2434\">Conclusion</h6><p data-start=\"2435\" data-end=\"2704\">PhD is the highest level of education that builds expertise in a specific subject. It is ideal for students who want to pursue careers in research, teaching, or advanced professional roles. A PhD contributes significantly to knowledge creation and academic development.</p>', 'PhD is a research-based doctoral program that allows students to specialize in a subject and contribute original research. It is ideal for those interested in academics, research, and higher-level expertise.', 'Ph.D', 'PhD is a research-based doctoral program that allows students to specialize in a subject and contribute original research. It is ideal for those interested in academics, research, and higher-level expertise.', 'phd', NULL, '1', '2026-04-17 13:26:57', '2026-04-17 13:26:57');

