DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(255) NOT NULL,
  `connection` text NOT NULL,
  `queue` text NOT NULL,
  `payload` longtext NOT NULL,
  `exception` longtext NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `home_abouts`;
CREATE TABLE `home_abouts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `heading` varchar(255) NOT NULL,
  `subheading` text NOT NULL,
  `image` varchar(255) NOT NULL,
  `icon_point_1` text NOT NULL,
  `icon_image_1` varchar(255) NOT NULL,
  `icon_point_2` text NOT NULL,
  `icon_image_2` varchar(255) NOT NULL,
  `multiple_points` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `home_abouts` (`id`, `heading`, `subheading`, `image`, `icon_point_1`, `icon_image_1`, `icon_point_2`, `icon_image_2`, `multiple_points`, `created_at`, `updated_at`) VALUES ('1', 'Goa Global Academy of Higher Education', 'Goa Correspondence College is   the pioneering   distance-learning institution in Goa, dedicated to making higher education accessible to students from diverse backgrounds.@@@Decades ago Goans had to travel to far way places like,Karwar,Dharwad,Kolhapur,Pune  ,Hyderabad,Mysore etc to answer 10th,12th,B.A.,B.Com,BSc,M.A.,M.Com,M.Sc,etc exams under,Private,Correspondence and other modes of exams. Goa Correspondence College was  facilitating such students to complete all formalities and also provided support service,travel lodgings  etc.@@@Later on Goa Correspondence College also introduced the concept of EXAMS IN GOA,wherein students need not have to travel outside Goa to answer exams.@@@Currently  Goa Correspondence College helps  students to complete their education in various modes such as Regular,Correspondence ,Online,Open and Distance Education.@@@Goans have been trusting the services of Goa Correspondence College since the past 35+ years.Over 10,000+ students have passed through the services of Goa Correspondence College.@@@Guided by its vision of “Education for All,” the institution strives to deliver affordable and inclusive education, helping individuals enhance their knowledge, develop skills, and achieve their academic and career goals.', 'new-assets/img/vidya-campus_about_image.png', '#', '#', '#', '#', 'Flexible Learning System@@@Affordable Courses@@@Study Anywhere Anything Anytime', NULL, '2026-04-17 10:26:50');

