) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `home_faqs` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('1', 'What is distance education?', '<p>Distance education is a mode of learning where students can study remotely without attending regular classes. It allows flexibility and convenience through online or correspondence methods.</p>', '2026-04-11 08:41:17', '2026-04-11 08:41:17');
INSERT INTO `home_faqs` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('2', 'Is distance education degree valid?', '<p>Yes, distance education degrees are valid if they are obtained from recognized universities approved by UGC or other relevant authorities.</p>', '2026-04-11 08:41:39', '2026-04-11 08:41:39');
INSERT INTO `home_faqs` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('3', 'Can I study while working full-time?', '<p>Yes, distance and online education are specially designed for working professionals. You can manage your studies alongside your job with flexible schedules.</p>', '2026-04-11 08:42:04', '2026-04-11 08:42:04');
INSERT INTO `home_faqs` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES ('4', 'What courses are available in distance learning?', '<p>Various courses are available such as BA, BCom, BBA, MBA, MCA, MA, and many professional certification programs depending on the university.</p>', '2026-04-11 08:42:30', '2026-04-11 08:42:30');

DROP TABLE IF EXISTS `leads`;
CREATE TABLE `leads` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `contact` varchar(255) NOT NULL,
  `cv` varchar(255) DEFAULT NULL,
  `remark` text DEFAULT NULL,
  `qualification` text DEFAULT NULL,
  `state` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `course` varchar(255) DEFAULT NULL,
  `message` varchar(255) DEFAULT NULL,
  `gender` varchar(191) DEFAULT NULL,
  `father` varchar(191) DEFAULT NULL,
  `institutename` varchar(191) DEFAULT NULL,
  `instituteownername` varchar(191) DEFAULT NULL,
  `type` varchar(191) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

