DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) NOT NULL,
  `batch` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `model_has_permissions`;
CREATE TABLE `model_has_permissions` (
  `permission_id` bigint(20) unsigned NOT NULL,
  `model_type` varchar(255) NOT NULL,
  `model_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`permission_id`,`model_id`,`model_type`),
  KEY `model_has_permissions_model_id_model_type_index` (`model_id`,`model_type`),
  CONSTRAINT `model_has_permissions_permission_id_foreign` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `model_has_roles`;
CREATE TABLE `model_has_roles` (
  `role_id` bigint(20) unsigned NOT NULL,
  `model_type` varchar(255) NOT NULL,
  `model_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`role_id`,`model_id`,`model_type`),
  KEY `model_has_roles_model_id_model_type_index` (`model_id`,`model_type`),
  CONSTRAINT `model_has_roles_role_id_foreign` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `notices`;
CREATE TABLE `notices` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` text NOT NULL,
  `link` varchar(191) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `password_resets`;
CREATE TABLE `password_resets` (
  `email` varchar(255) NOT NULL,
  `token` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  KEY `password_resets_email_index` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `guard_name` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `detail` text NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `registrations`;
CREATE TABLE `registrations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(192) NOT NULL,
  `fname` varchar(191) NOT NULL,
  `mname` varchar(191) NOT NULL,
  `email` varchar(191) NOT NULL,
  `contact` varchar(191) NOT NULL,
  `dob` varchar(191) NOT NULL,
  `course` varchar(191) NOT NULL,
  `uni` varchar(191) DEFAULT NULL,
  `mode` varchar(191) DEFAULT NULL,
  `session` varchar(191) DEFAULT NULL,
  `adhar` varchar(191) NOT NULL,
  `category` varchar(191) DEFAULT NULL,
  `employment` varchar(191) DEFAULT NULL,
  `abc` varchar(191) DEFAULT NULL,
  `deb` varchar(191) DEFAULT NULL,
  `address` varchar(191) DEFAULT NULL,
  `board__uni_10` varchar(11) DEFAULT NULL,
  `subject_year_10` varchar(191) DEFAULT NULL,
  `passing_year_10` varchar(191) DEFAULT NULL,
  `grade_10` varchar(191) DEFAULT NULL,
  `board__uni_12` varchar(191) DEFAULT NULL,
  `subject_year_12` varchar(191) DEFAULT NULL,
  `passing_year_12` varchar(191) DEFAULT NULL,
  `grade_12` varchar(191) DEFAULT NULL,
  `board_uni_other` varchar(191) DEFAULT NULL,
  `subject_year_other` varchar(191) DEFAULT NULL,
  `passing_year_other` varchar(191) DEFAULT NULL,
  `grade_other` varchar(191) DEFAULT NULL,
  `other1_name` varchar(191) DEFAULT NULL,
  `other2_name` varchar(191) DEFAULT NULL,
  `other3_name` varchar(191) DEFAULT NULL,
  `other4_1` varchar(191) DEFAULT NULL,
  `other4_2` varchar(191) DEFAULT NULL,
  `other4_3` varchar(191) DEFAULT NULL,
  `other4_4` varchar(191) DEFAULT NULL,
  `other5_1` varchar(191) DEFAULT NULL,
  `other5_2` varchar(191) DEFAULT NULL,
  `other5_3` varchar(191) DEFAULT NULL,
  `other5_4` varchar(191) DEFAULT NULL,
  `adhcard` varchar(191) DEFAULT NULL,
  `proof` varchar(191) DEFAULT NULL,
  `proof2` varchar(191) DEFAULT NULL,
  `other1` varchar(191) DEFAULT NULL,
  `other2` varchar(191) DEFAULT NULL,
  `other3` varchar(191) DEFAULT NULL,
  `photo` varchar(191) DEFAULT NULL,
  `guardian_signature` varchar(191) DEFAULT NULL,
  `student_signature` varchar(191) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

