DROP TABLE IF EXISTS `role_has_permissions`;
CREATE TABLE `role_has_permissions` (
  `permission_id` bigint(20) unsigned NOT NULL,
  `role_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`permission_id`,`role_id`),
  KEY `role_has_permissions_role_id_foreign` (`role_id`),
  CONSTRAINT `role_has_permissions_permission_id_foreign` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `role_has_permissions_role_id_foreign` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `guard_name` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `site_settings`;
CREATE TABLE `site_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `logo` varchar(255) NOT NULL,
  `logo_f` varchar(192) DEFAULT NULL,
  `primary_contact` varchar(255) NOT NULL,
  `secondary_contact` varchar(255) DEFAULT NULL,
  `primary_email` varchar(255) NOT NULL,
  `secondary_email` varchar(255) DEFAULT NULL,
  `primary_address` text NOT NULL,
  `secondary_address` text DEFAULT NULL,
  `facebook` varchar(255) DEFAULT NULL,
  `instagram` varchar(255) DEFAULT NULL,
  `twitter` varchar(255) DEFAULT NULL,
  `linkedin` varchar(255) DEFAULT NULL,
  `youtube` varchar(255) DEFAULT NULL,
  `telegram` varchar(255) DEFAULT NULL,
  `pinterest` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `site_settings` (`id`, `logo`, `logo_f`, `primary_contact`, `secondary_contact`, `primary_email`, `secondary_email`, `primary_address`, `secondary_address`, `facebook`, `instagram`, `twitter`, `linkedin`, `youtube`, `telegram`, `pinterest`, `created_at`, `updated_at`) VALUES ('1', 'web-assets/img/logo-gga.svg', 'web-assets/img/logo-gga-white.svg', '+91 98817 88888', '+91 94220 58888', 'info@goaglobalacademy.edu.in', 'admissions@goaglobalacademy.edu.in', 'Ashirwad Bldg, opp. Raymonds & Hotel Meenakshi, Pajifond, Madgaon, Goa 403601', '104, 1st Floor, Next to Maxcell, Reliance Magnum, Above Navtara Hotel,\r\n\r\nOpp. Kadamba Bus Stand, Margao - Goa', 'https://www.facebook.com/goacorrespondencecolleges/', 'https://www.instagram.com/goacorrespondencecollege', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-25 08:40:54');

DROP TABLE IF EXISTS `sub_course_faqs`;
CREATE TABLE `sub_course_faqs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `course_id` bigint(11) NOT NULL,
  `sub_course_id` bigint(20) unsigned NOT NULL,
  `question` text NOT NULL,
  `answer` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sub_course_faqs_sub_course_id_foreign` (`sub_course_id`),
  CONSTRAINT `sub_course_faqs_sub_course_id_foreign` FOREIGN KEY (`sub_course_id`) REFERENCES `sub_courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `sub_courses`;
CREATE TABLE `sub_courses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `course_id` bigint(20) unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `alt` varchar(255) NOT NULL,
  `duration` varchar(255) NOT NULL,
  `eligibilty` varchar(255) NOT NULL,
  `fees` varchar(255) NOT NULL,
  `content` longtext NOT NULL,
  `short_content` text NOT NULL,
  `meta_title` varchar(255) NOT NULL,
  `meta_description` text NOT NULL,
  `slug` varchar(255) NOT NULL,
  `ld_schema` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `testimonials`;
CREATE TABLE `testimonials` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `course_id` int(11) NOT NULL,
  `rating` int(11) NOT NULL,
  `content` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `testimonials` (`id`, `name`, `image`, `course_id`, `rating`, `content`, `created_at`, `updated_at`) VALUES ('1', 'Rahul Sharma', 'new-assets/img/testimonials/Rahul Sharma_testimonials.jpg', '1', '5', 'The flexible learning system helped me continue my studies while working full-time. The course structure was simple, practical, and very informative.', '2026-04-11 07:42:06', '2026-04-11 07:42:06');
INSERT INTO `testimonials` (`id`, `name`, `image`, `course_id`, `rating`, `content`, `created_at`, `updated_at`) VALUES ('2', 'Rahul Sharma', 'new-assets/img/testimonials/Rahul Sharma_testimonials.jpg', '1', '5', 'The flexible learning system helped me continue my studies while working full-time. The course structure was simple, practical, and very informative.', NULL, NULL);
INSERT INTO `testimonials` (`id`, `name`, `image`, `course_id`, `rating`, `content`, `created_at`, `updated_at`) VALUES ('3', 'Priya Verma', 'new-assets/img/testimonials/Rahul Sharma_testimonials.jpg', '1', '5', 'I had a great experience studying here. The support team was always responsive and the study material was well structured and easy to understand.', NULL, NULL);
INSERT INTO `testimonials` (`id`, `name`, `image`, `course_id`, `rating`, `content`, `created_at`, `updated_at`) VALUES ('4', 'Aman Singh', 'new-assets/img/testimonials/Rahul Sharma_testimonials.jpg', '1', '4', 'This platform gave me the opportunity to upgrade my technical skills without attending regular classes. Highly recommended for working professionals.', NULL, NULL);
INSERT INTO `testimonials` (`id`, `name`, `image`, `course_id`, `rating`, `content`, `created_at`, `updated_at`) VALUES ('5', 'Neha Gupta', 'new-assets/img/testimonials/Rahul Sharma_testimonials.jpg', '1', '5', 'The courses are affordable and provide real value. I was able to complete my graduation smoothly without any stress or complications.', NULL, NULL);
INSERT INTO `testimonials` (`id`, `name`, `image`, `course_id`, `rating`, `content`, `created_at`, `updated_at`) VALUES ('6', 'Rohit Kumar', 'new-assets/img/testimonials/Rahul Sharma_testimonials.jpg', '1', '4', 'Excellent learning experience! The flexibility and quality of education exceeded my expectations. Everything was well managed.', NULL, NULL);

