118);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\">Best for working students &amp; professionals</td></tr><tr style=\"border-bottom-width:1px;border-color:rgb(231, 237, 242);border-left-width:0px;border-right-width:0px;border-style:solid;border-top-width:1px;box-sizing:border-box;outline:none;\"><td style=\"--bs-table-accent-bg:rgba(var(--dark-rgb),0.0125);--bs-table-bg-type:rgba(0,0,0, 0.05);--bs-table-color-type:#000;background-color:rgb(255, 255, 255);border-bottom-width:0px;border-color:inherit;border-left-width:1px;border-right-width:1px;border-style:solid;border-top-width:0px;box-shadow:rgba(0, 0, 0, 0.05) 0px 0px 0px 9999px inset;box-sizing:border-box;color:rgb(78, 85, 97);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\"><strong style=\"box-sizing:border-box;outline:none;\">Pros</strong></td><td style=\"--bs-table-accent-bg:rgba(var(--dark-rgb),0.0125);--bs-table-bg-type:rgba(0,0,0, 0.05);--bs-table-color-type:#000;background-color:rgb(255, 255, 255);border-bottom-width:0px;border-color:inherit;border-left-width:1px;border-right-width:1px;border-style:solid;border-top-width:0px;box-shadow:rgba(0, 0, 0, 0.05) 0px 0px 0px 9999px inset;box-sizing:border-box;color:rgb(78, 85, 97);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\">Recognized degrees, placement help, student-friendly LMS, global exposure</td></tr><tr style=\"border-bottom-width:1px;border-color:rgb(231, 237, 242);border-left-width:0px;border-right-width:0px;border-style:solid;border-top-width:1px;box-sizing:border-box;outline:none;\"><td style=\"background-color:rgb(255, 255, 255);border-bottom-width:0px;border-color:inherit;border-left-width:1px;border-right-width:1px;border-style:solid;border-top-width:0px;box-shadow:rgba(0, 0, 0, 0) 0px 0px 0px 9999px inset;box-sizing:border-box;color:rgb(101, 107, 118);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\"><strong style=\"box-sizing:border-box;outline:none;\">Cons</strong></td><td style=\"background-color:rgb(255, 255, 255);border-bottom-width:0px;border-color:inherit;border-left-width:1px;border-right-width:1px;border-style:solid;border-top-width:0px;box-shadow:rgba(0, 0, 0, 0) 0px 0px 0px 9999px inset;box-sizing:border-box;color:rgb(101, 107, 118);font-size:14px;outline:none;padding:8px 20px;vertical-align:middle;white-space:nowrap;\">Limited in-person networking &amp; campus experience</td></tr></tbody></table></figure></div></figure></div></div>', 'Lovely Professional University Online (LPU Online) is one of India’s leading NAAC A++ accredited and UGC-entitled universities providing flexible and industry-oriented online degree programs. With advanced digital learning systems and global academic exposure, LPU Online offers UG and PG programs such as MBA, BBA, BCA, B.Com, MCA & MA, designed for students and working professionals aiming to upgrade their education without compromising work or location.\r\n\r\nIts modern LMS, interactive learning modules, affordable fee structure, EMI options, dedicated placement support, and real-world project training make it a preferred choice among online learners seeking recognized and career-focused education.', 'lpu-online', 'Lovely Professional University Online (LPU Online) is one of India’s leading NAAC A++ accredited and UGC-entitled universities providing flexible and industry-oriented online degree programs. With advanced digital learning systems and global academic exposure, LPU Online offers UG and PG programs such as MBA, BBA, BCA, B.Com, MCA & MA, designed for students and working professionals aiming to upgrade their education without compromising work or location.\r\n\r\nIts modern LMS, interactive learning modules, affordable fee structure, EMI options, dedicated placement support, and real-world project training make it a preferred choice among online learners seeking recognized and career-focused education.', 'lpu-online', NULL, '1', '2026-04-15 12:02:33', '2026-04-15 12:44:18');

DROP TABLE IF EXISTS `university_faqs`;
CREATE TABLE `university_faqs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `university_id` bigint(20) unsigned NOT NULL,
  `question` text NOT NULL,
  `answer` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `university_faqs_university_id_foreign` (`university_id`),
  CONSTRAINT `university_faqs_university_id_foreign` FOREIGN KEY (`university_id`) REFERENCES `universities` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `university_modes`;
CREATE TABLE `university_modes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `university_modes` (`id`, `name`, `slug`, `created_at`, `updated_at`) VALUES ('1', 'Online-Distance', 'online-distance', '2026-04-15 11:58:48', '2026-04-15 11:59:18');
